(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-vae-tiled-decode"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-1\">一 · 事故现场：一次 4K 出图请求把解码卡打成了 OOM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-2\">二 · 显存峰值从哪里来：整图解码的代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-3\">三 · 机制的数据流：切块、halo、融合、流水</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-4\">四 · 一个具体例子：4K 请求的两种命运</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-5\">五 · 适用边界：它不解决什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-6\">六 · 工程判断：什么时候该上，什么时候不该上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-7\">七 · 分块解码的失效边界：它救的是显存，不是所有瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-8\">八 · 从 latent 落盘到 tile 视图：切分前的缓冲区语义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-9\">九 · tile 网格与 halo：把切分参数变成显存与算力的交换率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-10\">十 · 逐块上采样：单 tile 解码的输入输出与三类代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-11\">十一 · 输出缓冲区的按位写入与重叠区加权融合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-12\">十二 · 跨 stream 流水：解码与下一请求采样的重叠时序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-13\">十三 · 分块解码的失效边界与流水代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-14\">十四 · 显存峰值公式的逐项拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-15\">十五 · 时延公式与流水隐藏的推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-16\">十六 · halo 与加权融合的可实现形式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-17\">十七 · 通道维拼接与缓冲区布局</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-18\">十八 · 复杂度与调参的工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-19\">十九 · 边界条件：halo 与 tile 的耦合代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-20\">二十 · 请求形态：什么样的解码请求值得分块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-21\">二十一 · 批大小与 tile 尺寸的耦合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-22\">二十二 · 并发形态与流水重叠的负载前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-23\">二十三 · 负载不对时的失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-24\">二十四 · 配方表与准入判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-25\">二十五 · 工程判断的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-26\">二十六 · 硬件档位：按 tile 工作集而非整图峰值选卡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-27\">二十七 · 并行拓扑：tile 内串行、tile 间与请求间两级并行</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-28\">二十八 · 量化方案：解码器权重量化与激活精度分层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-29\">二十九 · KV 策略：解码阶段无 KV，缓冲区即状态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-30\">三十 · 调度参数：tile 队列、stream 配比与融合时机</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-31\">三十一 · 可复现配置思路：从公式反推参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-32\">三十二 · 配方失效的三个断点：halo 预算、tile 下限与 stream 同步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-33\">三十三 · 显存账本：峰值、驻留与批容量的三角约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-34\">三十四 · 带宽墙：halo 重复读取与写回放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-35\">三十五 · 通信与流水：跨 stream 同步的真实开销</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-36\">三十六 · 功耗与利用率：小 kernel 的空转成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-37\">三十七 · 尾延迟：分块带来的长尾与不均衡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-38\">三十八 · 规模上限的判定顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-39\">三十九 · 分块解码的规模天花板：显存、带宽与尾延迟谁先失守</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-40\">四十 · 精度失败：halo 融合参数与边界接缝的定位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-41\">四十一 · OOM 复发：tile 尺寸与 halo 的显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-42\">四十二 · 批抖动与路由不均：流水重叠下的排队形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-43\">四十三 · 尾延迟尖刺：从 tile 队列深度到融合 kernel</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-44\">四十四 · 监控与回滚：可观测项与灰度策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-45\">四十五 · 边界之外：分块解码的五类失效与可回滚的观测面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-46\">四十六 · 对照轴：显存峰值、kernel 粒度与流水位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-47\">四十七 · 决策表：四种形态的适用条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-48\">四十八 · 与特征缓存、块级跳步的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-49\">四十九 · 与混合精度分块、FP8/NVFP4 路径的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-50\">五十 · 与阶段级服务流水的组合与冲突</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-51\">五十一 · 选型判据的落地：三个可测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vae-tiled-decode-sec-52\">五十二 · 分块解码的选型边界：三条路线的决策表</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">DiT 采样完成，latent 写入显存缓冲区</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按 tile 尺寸切分 latent，块间保留 halo 重叠区</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">逐块送入 VAE 解码器上采样，输出写入输出缓冲区对应位置</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">重叠区做加权融合，消除块边界接缝</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码与下一请求的 DiT 采样在不同 stream 上流水重叠</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-vae-tiled-decode-sec-1\">一 · 事故现场：一次 4K 出图请求把解码卡打成了 OOM</h3>\n<p>先把场景摆出来。某条线上扩散服务链路，DiT 采样阶段跑得好好的，latent 在显存里躺得安安稳稳，直到 VAE 解码这一步把整张 latent 一次性喂进解码器做上采样。高分辨率请求进来时，单次上采样激活显存峰值可达数十 GB——注意，这还只是激活，不含权重和 KV 之外的其他常驻。于是事故的形态很固定：要么直接 OOM 把进程打挂，要么框架的显存保护机制介入，被迫把 batch 降到 1，甚至把请求排队延后。无论哪种，解码阶段都从“顺带做完的一步”变成了服务端的显存与吞吐瓶颈。</p>\n<p>这个事故值得拆开看，因为它暴露的不是某个 kernel 写得不好，而是<strong>解码阶段的显存需求与采样阶段的显存需求在量级上不匹配</strong>。DiT 采样是迭代式的，每步只处理一份 latent，激活可控；VAE 解码是一次性上采样，空间维度被放大若干倍，通道维同时展开，激活峰值随 $H\\cdot W$ 线性膨胀。当 $H\\cdot W$ 大到 4K 量级，这条曲线就撞上了单卡显存的天花板。工程上常见的错误应对是“加卡”——但解码是单请求内部的串行上采样，张量并行切不动空间维度的激活峰值，加卡并不能把这一次上采样的峰值摊薄。真正的问题是：<em>有没有办法让解码的显存峰值不随整图面积走，而是随一个可控的块面积走。</em></p>\n<p>这就是 VAE 分块解码要解决的具体推理问题。它的目标非常窄：把一次整图上采样拆成若干次小块上采样，让显存峰值从“整图量级”降到“单块量级”，从而让高分辨率请求不再 OOM、batch 容量不再被解码阶段压死。它不解决 DiT 采样本身的显存问题，不解决权重加载与常驻开销，也不解决跨请求的调度公平性——那些是别的条目的事。把边界划清楚，后面的机制才有意义。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-2\">二 · 显存峰值从哪里来：整图解码的代价结构</h3>\n<p>要理解分块为什么有效，得先看清整图解码的峰值构成。VAE 解码器是一串上采样与卷积/注意力的组合，每一层都会产生中间激活。整图解码时，这些激活的空间尺寸是整张输出图的尺寸，通道数在中后段往往不小，于是峰值近似正比于 $H\\cdot W\\cdot C_{\\text{dec}}$，其中 $C_{\\text{dec}}$ 是解码器在该峰值层的等效通道开销。这就是“数十 GB”的来源：不是某一个张量特别大，而是整条上采样链在最大空间尺度上同时驻留了若干份激活。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}} + M_{\\text{halo}},\\quad T_{\\text{decode}} \\approx \\sum_{i} T_{\\text{tile},i} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$$</div>\n<p>第一项说明分块的直接收益：把空间切成 $n_{\\text{tile}}\\times n_{\\text{tile}}$ 个块，单块激活面积是整图的 $1/n_{\\text{tile}}^2$，峰值随之下降。第二项 $M_{\\text{halo}}$ 是重叠区带来的额外显存，它是分块的必要代价而非副作用——没有 halo，块边界就会露馅。时延公式里的 $\\kappa$ 是分块开销系数，$\\kappa&gt;1$ 反映 halo 重复计算、kernel launch 频繁、GPU 利用率下降这些损耗。两个公式合起来就是这套算法的全部工程张力：<strong>用 $\\kappa$ 换 $1/n_{\\text{tile}}^2$ 的显存下降</strong>。</p>\n<p>这里必须点明一个容易被忽略的事实：分块降低的是<em>激活峰值</em>，不是权重显存，也不是输出缓冲区。输出缓冲区仍然是整图大小——因为最终要拼回一张完整图。所以分块解码的显存下限由“输出缓冲区 + 单块激活 + halo”共同决定，当输出图本身大到接近显存上限时，分块也救不了。这就是适用边界的第一条硬线。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-3\">三 · 机制的数据流：切块、halo、融合、流水</h3>\n<p>按数据流顺序走一遍，机制的每一步都对应一个工程决策。第一步，DiT 采样完成，latent 写入显存缓冲区——这一步看似平凡，但它决定了后续流水重叠能否成立：latent 必须在一个稳定的缓冲区里，解码才能与下一请求的采样并行。第二步，按 tile 尺寸切分 latent，块间保留 halo 重叠区。halo 的宽度不是随手定的，它要覆盖解码器感受野在边界处的影响范围；感受野越大、上采样倍率越高，halo 越宽，$M_{\\text{halo}}$ 与重复计算量越大。</p>\n<p>第三步，逐块送入 VAE 解码器上采样，输出写入输出缓冲区对应位置。第四步，重叠区做加权融合，消除块边界接缝。加权融合的本质是在 halo 带内用平滑权重把相邻块的结果混合，避免硬拼接产生的亮度跳变与结构断裂。第五步，解码与下一请求的 DiT 采样在不同 stream 上流水重叠——这一步是吞吐的关键：解码的计算密度低、kernel 小，正好可以填进采样阶段留下的空隙。</p>\n<ul>\n<li><strong>切分</strong>：tile 尺寸是唯一的核心调参量，过大则显存回升，过小则 launch 频繁。</li>\n<li><strong>halo</strong>：宽度由感受野与上采样倍率决定，直接进入 $M_{\\text{halo}}$ 与 $\\kappa$。</li>\n<li><strong>融合</strong>：加权参数不当会在边界留下接缝与亮度跳变，这是最典型的伪影失败模式。</li>\n<li><strong>流水</strong>：不同 stream 上的重叠要求缓冲区复用正确，否则解码可能读到未写完的 latent。</li>\n</ul>\n<p>代价要算清楚。分块解码的 kernel 形状小、launch 频繁，GPU 利用率低于整图解码——整图解码一次 launch 吃满大张量，分块则是几十上百次小 launch，调度开销占比上升。这就是 $\\kappa$ 的主要来源。工程对策是融合 kernel：把切块、解码、写回、融合尽量压进更少的 launch 里，把 $\\kappa$ 拉回接近 1。没有这一步，分块省下的显存会被时延吃掉，高分辨率请求的端到端 SLO 反而更难看。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-4\">四 · 一个具体例子：4K 请求的两种命运</h3>\n<p>设一个高分辨率 latent 解码请求，整图解码的激活峰值落在数十 GB 档位。整图路径下，这张卡上同时还要放 DiT 权重、latent 缓冲、输出缓冲，峰值一撞顶就 OOM；框架退让到 batch=1，解码独占显存，采样阶段只能等——端到端时延里解码部分完全暴露，吞吐被单请求串行锁死。这是第一种命运。</p>\n<p>分块路径下，同一请求被切成 $n_{\\text{tile}}\\times n_{\\text{tile}}$ 个块，单块激活降到整图的 $1/n_{\\text{tile}}^2$，峰值变成 $M_{\\text{tile}}+M_{\\text{halo}}$ 量级，OOM 消失，batch 容量回升。同时解码被放到与下一请求采样不同的 stream 上，解码时延被采样时延遮住，端到端时延中解码部分被隐藏。这是第二种命运。差别不在硬件，而在“解码的显存需求是否随整图面积走”。</p>\n<p>但第二种命运不是免费的。halo 重叠带来额外计算，融合带来边界伪影风险，tile 尺寸调参不当会让显存回升或利用率崩塌。更隐蔽的是流水重叠的正确性：如果 stream 同步写错，或者显存缓冲区复用出错，解码会读到未写完的 latent，输出缓冲区出现竞争——这类 bug 不报错，只出脏图，排查成本极高。所以这套算法的稳定性技巧必须和机制一起交付：重叠 halo 加加权融合抑制接缝，缓冲区生命周期用显式事件同步锁死。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-5\">五 · 适用边界：它不解决什么</h3>\n<p>把边界说透，比把优点说满更有用。这套算法适用于高分辨率 latent 解码、整图解码显存峰值达数十 GB 的场景——也就是解码阶段确实是服务端显存与吞吐瓶颈的场合。它的规模上限受 tile 尺寸与 halo 开销约束：halo 重叠增加显存与算力，分块 kernel 利用率低于整图解码，当输出图本身逼近显存上限时，输出缓冲区这一项就把分块的路堵死了。</p>\n<p>它不解决的问题清单同样明确。第一，它不降低 DiT 采样的激活与权重开销——采样阶段的显存问题要靠采样侧的优化，与本算法无关。第二，它不改变解码器的数值精度路径，量化与精度方案是另一条线的事。第三，它不替代扩散流水线的阶段级服务：后者把 VAE 解码拆成独立 stage 做跨请求调度，本算法是在解码内部做分块与流水重叠，两者是不同层次的切分，可以叠加但不能互相顶替。第四，它不解决跨请求的公平调度与优先级，那是批调度与连续批处理的地盘。</p>\n<p>还有一条边界常被误读：分块解码不是“把大图变小图”。它切的是计算的空间域，输出仍是整图分辨率，通道维拼接保证结果与整图解码在数值上一致（在 halo 融合正确的前提下）。因此它不能用来做分辨率降级换吞吐——那是混合分辨率补丁调度要处理的问题。把这两件事混为一谈，会在容量规划时得出错误结论。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-6\">六 · 工程判断：什么时候该上，什么时候不该上</h3>\n<p>给出可操作的判断线。当线上出现“高分辨率请求 OOM 或被迫降 batch，且瓶颈定位在 VAE 解码的上采样激活”时，这套算法是对症的；当瓶颈在采样阶段的迭代时延、在权重加载、在跨请求排队时，上分块解码只会增加 $\\kappa$ 而不解决根因。判断依据不是请求分辨率本身，而是<em>解码激活峰值与可用显存余量的比值</em>：比值接近 1 时，分块是唯一出路；比值远小于 1 时，整图解码的 GPU 利用率更高，分块反而亏。</p>\n<p>上马之后，第一优先级不是调 tile 尺寸，而是把流水重叠的缓冲区生命周期用显式同步锁死——正确性 bug 比性能损失贵得多。第二优先级才是 tile 尺寸与 halo 宽度的联合调参：先按感受野定 halo 下限，再按显存余量定 tile 上限，最后用融合 kernel 把 launch 开销压下去。第三优先级是融合权重的标定，用边界带的亮度连续性做验收指标，而不是只看整图 PSNR——接缝是局部现象，全局指标会把它平均掉。</p>\n<p>最后落在机制上：这套算法的本质是把解码的显存峰值从“整图面积函数”改写成“单块面积函数加 halo 常数”，代价是 $\\kappa$ 与边界伪影风险。它成立的充要工程条件是——输出缓冲区放得下、halo 融合参数标得准、流水同步写得对。三者缺一，分块解码就从“救火”变成“换一种方式着火”。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-7\">七 · 分块解码的失效边界：它救的是显存，不是所有瓶颈</h3>\n<p>先把适用面钉死：这个算法唯一要治的是“整图一次性 VAE 解码时单次上采样激活显存峰值冲到数十 GB”这一类问题。典型事故形态是——高分辨率 latent 请求进来，整图解码在第一个上采样层就把显存打满，进程 OOM 被杀，或框架被动把 batch 降到 1，解码阶段随即变成服务端的显存与吞吐双重瓶颈，前面 DiT 采样再快也被这一段拖住。分块把峰值压到单 tile 量级，关系是 <span class=\"formula\">$$M_{\\text{peak}}\\approx M_{\\text{tile}}+M_{\\text{halo}}$$</span>，于是高分辨率请求不再 OOM、batch 容量回升。但它不解决算力不足、不解决 DiT 采样本身的时延、也不解决通信与调度问题——整图解码本来就不 OOM 的中低分辨率请求，套上分块只会白付 halo 与 kernel launch 的代价。</p>\n<p>失效条件集中在三处。其一，halo 重叠区不足或加权融合参数不当，块边界出现接缝与亮度跳变，高分辨率图像伪影肉眼可见——这是把显存问题换成了质量问题。其二，tile 尺寸调参不当：过大则显存峰值回升重新触发 OOM，过小则 kernel 形状碎、launch 频繁，GPU 利用率低于整图解码，此时 <span class=\"formula\">$$T_{\\text{decode}} \\approx \\sum_{i} T_{\\text{tile},i} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$$</span> 中的 $\\kappa&gt;1$ 会把分块的理论收益吃掉，甚至倒挂。其三，解码与下一请求 DiT 采样在不同 stream 上流水重叠时，stream 同步或显存缓冲区复用出错，解码读到未写完的 latent，或输出缓冲区发生竞争——这类错误不报 OOM，只产出脏数据，比崩溃更难查。</p>\n<p>系统代价要按“省下的显存”与“多付的开销”两头记账。显存侧收益是数量级的：峰值从整图激活降到单 tile 加 halo；吞吐侧收益来自 batch 容量提升与解码时延被采样流水隐藏。代价侧则是 halo 带来的额外显存与算力、融合步骤的额外带宽，以及小 kernel 的利用率损失。工程判断很直接：只有当整图解码峰值确实逼近显存上限、且端到端 SLO 中解码占比不可忽略时，分块才划算；否则应优先走整图解码加融合 kernel 的简单路径。落地时必须把 tile 尺寸按模型逐档实测标定，并把分块解码的多个小 kernel 融合成少量大 kernel，否则省下的显存会被 launch 开销和低利用率反噬。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>分块解码表现</th></tr></thead><tbody><tr><td>整图峰值达数十 GB、高分辨率请求</td><td>消除 OOM，batch 容量提升，收益明确</td></tr><tr><td>整图本就不 OOM 的中低分辨率</td><td>净亏：halo 算力与 launch 开销无对应收益</td></tr><tr><td>tile 过大 / halo 不足</td><td>显存回升或边界接缝、亮度跳变</td></tr><tr><td>tile 过小、kernel 未融合</td><td>利用率低于整图解码，$\\kappa$ 抬升抵消收益</td></tr></tbody></table>\n<h3 id=\"alg-vae-tiled-decode-sec-8\">八 · 从 latent 落盘到 tile 视图：切分前的缓冲区语义</h3>\n<p>分块解码的第一步不是切，而是<strong>确认 latent 已经完整落在显存里、并且可以被多个 stream 安全读取</strong>。DiT 采样结束时，最后一步去噪的输出张量通常还挂在采样 stream 的临时分配区上，形状为 $[B, C_{\\text{lat}}, H_{\\text{lat}}, W_{\\text{lat}}]$，其中 $H_{\\text{lat}},W_{\\text{lat}}$ 是 latent 空间分辨率，$C_{\\text{lat}}$ 是 latent 通道数。这一步的输出是「一份可被解码 stream 引用的稳定 latent 缓冲」，输入则是采样 kernel 的最后一个输出。代价很直接：这块缓冲必须按 batch 内最大请求的 latent 尺寸预留，否则后续切分时会出现重分配与拷贝；对高分辨率请求，latent 本身虽远小于解码激活，但乘以在飞请求数后仍是显存规划中的固定项。</p>\n<p>工程上要把这一步做成显式的<strong>所有权移交</strong>：采样 stream 记录一个 event，解码 stream 在该 event 之后才可读 latent；缓冲区的生命周期由请求级引用计数管理，而不是由某个 stream 的局部作用域管理。否则就会出现失败模式中那类问题——解码读到尚未写完的 latent，输出块出现整块噪声而非接缝。这一步不产生浮点计算，但它是后面所有流水重叠的前提：没有跨 stream 的可见性契约，重叠就是竞态。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-9\">九 · tile 网格与 halo：把切分参数变成显存与算力的交换率</h3>\n<p>切分步骤的输入是 latent 缓冲与一组切分参数，输出是一张 tile 描述表：每个 tile 的 latent 起始坐标、尺寸、以及向外扩展的 halo 宽度。设 latent 被切成 $n_{\\text{tile}}\\times n_{\\text{tile}}$ 的网格，单 tile 的 latent 覆盖面积为 $(H_{\\text{lat}}/n_{\\text{tile}}+2h)\\times(W_{\\text{lat}}/n_{\\text{tile}}+2h)$，其中 $h$ 为 halo 在半分辨率下的等效宽度。halo 的作用是让每个 tile 在解码时看到边界外的上下文，使上采样卷积与注意力在块边缘处的感受野不被硬切断；融合阶段再把这些重叠区按权重折回。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}} + M_{\\text{halo}},\\quad T_{\\text{decode}} \\approx \\sum_{i} T_{\\text{tile},i} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$$</div>\n<p>第一项说明显存峰值随 $n_{\\text{tile}}^2$ 反比下降，$C_{\\text{dec}}$ 是解码器在像素空间每像素的激活系数；第二项 $M_{\\text{halo}}$ 是 halo 带来的额外激活，随 $h$ 线性增长。第二式中的 $\\kappa&gt;1$ 是分块相对整图解码的算力放大因子，来源正是 halo 重叠区的重复计算与融合开销。这就是切分参数的本质：<strong>用 $\\kappa$ 换显存</strong>。tile 取得过大，$M_{\\text{peak}}$ 回升到接近整图量级，OOM 风险回来；tile 取得过小，$\\kappa$ 上升且 kernel 形状变小、launch 次数按 $n_{\\text{tile}}^2$ 增长，GPU 利用率下滑。这一步的输出不是数据，而是后续调度与 kernel 选择的约束条件，因此 tile 描述表要连同每块的 halo 宽度、融合权重一起下发，不能只给一个网格尺寸。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-10\">十 · 逐块上采样：单 tile 解码的输入输出与三类代价</h3>\n<p>对描述表中的每个 tile，输入是该 tile 的 latent 切片（含 halo），输出是像素空间的上采样结果，写入输出缓冲区的对应位置。单 tile 解码内部走的是完整的 VAE 解码器前向：若干级上采样、归一化与残差，激活尺寸在像素空间达到 $H_{\\text{tile}}\\times W_{\\text{tile}}\\times C_{\\text{dec}}$。这一步的代价要分三类看。</p>\n<ul>\n<li><strong>显存</strong>：峰值由单 tile 激活主导，即 $M_{\\text{tile}}$ 项；这是分块真正买到的东西——把数十 GB 量级的整图激活压到单 tile 量级，高分辨率请求不再触发 OOM，batch 容量随之提升。</li>\n<li><strong>延迟</strong>：单 tile 的计算量约为整图的 $1/n_{\\text{tile}}^2$ 乘以 $\\kappa$ 中的重复部分；但小形状 kernel 的 launch 开销占比上升，单块的有效算力利用率低于整图解码，因此 $T_{\\text{tile},i}$ 并不严格按面积等比缩小。</li>\n<li><strong>带宽</strong>：每个 tile 都要把 latent 切片读入、把像素输出写出，halo 区被相邻 tile 重复读取，输出缓冲区的写入是分散的按块写。带宽压力不在单块峰值，而在块数乘以每块的读写量。</li>\n</ul>\n<p>具体例子：一个 batch 内混有高分辨率与常规分辨率请求时，若按最大请求的整图激活预留，batch 会被迫降到很小；切分后每个请求按自己的 tile 表解码，显存占用按 tile 计，调度器可以把更多请求塞进同一 batch。这里的工程判断是：<strong>tile 尺寸要按模型调参而非按请求调参</strong>，同一模型内保持统一 tile 形状，才能让 kernel 形状稳定、减少形状特化带来的编译与调度开销；请求间的差异体现在 tile 数量上，而不是 tile 大小上。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-11\">十一 · 输出缓冲区的按位写入与重叠区加权融合</h3>\n<p>逐块解码的输出不是直接可用的图像，而是若干在边界处重叠的像素块。融合步骤的输入是输出缓冲区中所有已写入的 tile 及其权重掩码，输出是消除了接缝的完整像素张量。做法是对重叠区按距离边界的远近做加权：块中心权重高、块边缘权重低，两个相邻块在同一像素上的权重之和归一化。伪代码思路如下：</p>\n<ul>\n<li>为每个 tile 预生成一张与像素块同形状的权重图，边缘按 halo 宽度线性或平滑衰减；</li>\n<li>解码结果写入时同时写入权重，累加到输出缓冲区的分子与分母两个累加器；</li>\n<li>全部 tile 完成后做一次逐像素除法，得到融合结果。</li>\n</ul>\n<p>代价在于：累加器使输出缓冲区的显存翻倍（分子加分母），这是一笔容易被忽略的固定开销，在高分辨率下与单 tile 激活同量级；融合本身是一次全图逐元素运算，带宽受限，读两遍写一遍。失败模式很明确——halo 宽度不足或衰减参数不当，块边界出现接缝与亮度跳变，高分辨率图像上尤其明显。因此 halo 宽度必须覆盖解码器中有效感受野的最大半径，而不是拍一个经验值；加权融合的参数要与 tile 尺寸一起进入调参流程，二者不匹配时，显存省下来了但画质塌了。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-12\">十二 · 跨 stream 流水：解码与下一请求采样的重叠时序</h3>\n<p>最后一步是把解码放回服务流水。输入是当前请求已完成的 latent 与下一请求正在进行的 DiT 采样，输出是两条 stream 上交错执行的时序。解码在独立 stream 上按 tile 推进，采样 stream 继续为下一个请求去噪；两者通过 event 做单向同步：解码等待 latent 就绪 event，采样不等待解码完成，只在下一次复用 latent 缓冲区前等待解码的释放 event。</p>\n<p>这一步买到的是端到端时延中解码部分的隐藏：$T_{\\text{e2e}}\\approx \\max(T_{\\text{sample}},T_{\\text{decode}})+T_{\\text{residual}}$，当解码被完全隐藏时，$T_{\\text{residual}}$ 只剩同步与融合的尾巴。代价有三处：其一，两条 stream 同时占用显存，解码的 tile 激活与采样的注意力/KV 激活叠加，显存规划要按并发峰值而非单阶段峰值做；其二，SM 资源竞争使采样的单步延迟上升，重叠不是免费的，它把解码的时延换成了采样的轻微减速；其三，缓冲区复用出错就会回到第一节那个竞态——解码读到未写完的 latent，或输出缓冲区被下一请求覆盖。</p>\n<p>工程判断落在同步粒度上：按请求级 event 同步而不是按 tile 级同步，能避免每块一次 event 记录的开销；但请求级同步要求 latent 缓冲区按请求隔离，不能跨请求复用同一块物理显存，否则释放 event 的语义会变得难以推理。当解码时间显著短于采样时间时，重叠收益最大；当解码因小 kernel launch 频繁而变慢、接近甚至超过采样时间时，重叠只能隐藏一部分，此时应优先做 kernel 融合把 $\\kappa$ 压下来，而不是继续加大并发。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-13\">十三 · 分块解码的失效边界与流水代价账</h3>\n<p>这套方案的收益并非无条件的，它的边界由三个量共同钉死：tile 尺寸、halo 宽度、以及解码与采样两条 stream 的同步点。显存侧的关系可以写成 <span class=\"formula\">$$M_{\\text{peak}} \\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}} + M_{\\text{halo}}$$</span>，其中 $C_{\\text{dec}}$ 是单像素在解码器各上采样层上的激活系数，$M_{\\text{halo}}$ 是重叠区额外驻留的显存。注意第二项不随 $n_{\\text{tile}}$ 缩小而消失——halo 是按块边界周长而非面积增长的，块切得越碎，halo 占总激活的比例越高，显存曲线在某个 $n_{\\text{tile}}$ 之后不再下降甚至回升。这就是“tile 尺寸调参不当导致显存回升”的数学来源：过大的 tile 让第一项重新逼近数十 GB 量级触发 OOM，过小的 tile 让第二项与 kernel launch 开销同时膨胀。工程上必须实测这条 U 形曲线，而不是照搬某个固定 tile 边长。</p>\n<p>时延侧同样有一笔不能忽略的账：<span class=\"formula\">$$T_{\\text{decode}} \\approx \\sum_{i} T_{\\text{tile},i} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$$</span>，$\\kappa$ 是分块带来的效率折损因子，恒大于 1。它来自三处：每块解码的 kernel 形状变小、launch 频繁，GPU 占用率低于整图解码；halo 区被重复计算，算力按重叠比例浪费；重叠区加权融合本身是一次额外的逐元素读写。因此分块解码的“隐藏”只在它与下一请求的 DiT 采样在不同 stream 上真正并行时才成立——若采样阶段本身已把 SM 与显存带宽吃满，解码 stream 只能捡剩余资源，$\\kappa$ 会被放大，端到端时延反而可能劣化。判断标准很直接：解码阶段的显存带宽占用与采样阶段的带宽占用之和若超过单卡可持续带宽，流水重叠就退化为时间片轮转，隐藏效果消失。</p>\n<p>失效条件集中在三类。其一是伪影类：halo 宽度不足或加权融合的窗函数参数不当，块边界出现接缝与亮度跳变，在高分辨率输出上肉眼可辨；这类问题不会报错，只会让服务质量静默下降，必须用固定种子的小图做边界残差回归测试。其二是同步类：解码与 DiT 采样流水重叠时，若 stream 同步点或显存缓冲区复用出错，解码可能读到尚未写完的 latent，或两个请求竞争同一输出缓冲区；这类 bug 表现为间歇性花屏，定位成本高，正确做法是给 latent 缓冲与输出缓冲各设一个完成事件，解码 stream 只等待事件而非全局同步。其三是规模类：halo 开销随块数增长，规模上限受 tile 尺寸与 halo 共同约束，超过该上限后分块不再带来净收益。一张对照表可以把边界讲清楚：</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>边界接缝</td><td>halo 不足、融合窗参数不当</td><td>无报错的质量劣化</td></tr><tr><td>显存回升</td><td>tile 过大或过小</td><td>OOM 或利用率下降</td></tr><tr><td>流水退化</td><td>采样与解码争抢带宽</td><td>$\\kappa$ 放大、时延不降</td></tr><tr><td>缓冲竞争</td><td>stream 同步点缺失</td><td>间歇花屏、难复现</td></tr></tbody></table>\n<p>与把 VAE 解码拆成独立 stage 的扩散流水线服务相比，本方案在解码内部做切块与重叠，好处是不需要跨节点搬运整幅 latent 与输出，坏处是它把复杂度压进了单卡内部：tile 调度、halo 融合、双 stream 同步三件事耦合在同一进程里，任何一处参数漂移都直接反映为显存峰值或伪影。因此部署时的工程判断应落在“先定 halo 再定 tile”：halo 由解码器感受野与上采样倍率决定，是模型属性、不可随意压缩；tile 则在 halo 固定后按显存预算反解，并留出与采样 stream 并行时的带宽余量。融合 kernel 的优先级高于继续缩小 tile——把逐块解码与融合合并成少量大 kernel，压低 launch 频率，才是把 $\\kappa$ 拉回接近 1 的现实路径。</p>\n<h3 id=\"alg-vae-tiled-decode-sec-14\">十四 · 显存峰值公式的逐项拆解</h3>\n<p>分块解码的显存账不能只写一句“降到单 tile 量级”，必须把每一项拆开，才能判断 tile 尺寸该往哪个方向调。可用事实给出的核心关系是 <span class=\"formula\">$$M_{\\text{peak}}\\approx M_{\\text{tile}}+M_{\\text{halo}}$$</span>，而更展开的形式是 <span class=\"formula\">$$M_{\\text{peak}} \\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}} + M_{\\text{halo}}$$</span>。这里 $H\\cdot W$ 是 latent 的空间面积，$n_{\\text{tile}}$ 是每个空间维度上的切块数，因此 $n_{\\text{tile}}^2$ 是总块数，$\\frac{H\\cdot W}{n_{\\text{tile}}^2}$ 就是单块覆盖的 latent 面积。$C_{\\text{dec}}$ 是“单位 latent 面积在解码器内部产生的激活字节数”这一折算系数——它不是常数，而是随解码器层级变化的复合量：浅层上采样后特征图分辨率高、通道数少，深层分辨率低、通道数多，中间还有若干残差与归一化的临时缓冲。把 $C_{\\text{dec}}$ 写成单一系数是一种工程近似，它的取值由解码器结构决定，随模型而变，因此 tile 尺寸必须按模型实测调参，而不是套一个固定像素数。</p>\n<p>关键的一步推导在于：整图解码时峰值正比于 $H\\cdot W\\cdot C_{\\text{dec}}$，切块后每块只承担 $\\frac{H\\cdot W}{n_{\\text{tile}}^2}$ 的面积，于是激活项按 $n_{\\text{tile}}^2$ 反比缩小。这正是“数十 GB 峰值”被压到单 tile 量级的数学来源。但等式右边第二项 $M_{\\text{halo}}$ 不随 $n_{\\text{tile}}$ 缩小——相反，块数越多，halo 重叠区的总显存开销越大，因为每个块都要额外携带一圈重叠像素的输入与中间激活。于是存在一个最优点：继续增大 $n_{\\text{tile}}$ 会让第一项趋近于零，但第二项与 kernel launch 开销上升，收益递减。工程判断是：先把 $M_{\\text{halo}}$ 压到第一项的同一量级以下，再谈切得更细。</p>\n<p>代价面必须同时看：显存峰值下降换来 batch 容量提升，但 halo 重叠引入额外计算，且分块后 kernel 形状变小、launch 频繁，GPU 利用率低于整图解码。一个具体例子：高分辨率 latent 若整图解码激活峰值达数十 GB，在单卡上直接触发 OOM 或被迫把 batch 降到 1；按二维切块后，单块激活只占整图的 $1/n_{\\text{tile}}^2$，加上一圈 halo，峰值落到可控范围，batch 容量随之回升——具体批大小取决于 tile 与 halo 的显存约束，材料未给出数值，只能定性表述为“提升”。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-15\">十五 · 时延公式与流水隐藏的推导</h3>\n<p>时延侧的关系是 <span class=\"formula\">$$T_{\\text{decode}} \\approx \\sum_{i} T_{\\text{tile},i} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$$</span>。第一层等号是串行逐块解码的朴素和：$n_{\\text{tile}}^2$ 个块依次过解码器。第二层等号把单块时间折算成整图时间除以块数，再乘一个修正因子 $\\kappa$。$\\kappa$ 捕捉的是分块带来的非理想开销：每块都要多算 halo 重叠区，块边界处的融合要额外读写，小块 kernel 的 launch 与调度开销摊到更少的计算上，以及小形状下 SM 占用率下降导致的单位算力效率损失。$\\kappa&gt;1$ 是常态，它衡量“切块本身值不值”。</p>\n<p>推导的关键一步是认识到 $\\kappa$ 与 $n_{\\text{tile}}$ 同向增长：块切得越细，halo 占比越高、launch 次数越多、单块算术强度越低，$\\kappa$ 越大。于是 $T_{\\text{decode}}$ 并不随 $n_{\\text{tile}}^2$ 线性下降，而是下降变缓甚至反弹。这解释了为什么 tile 尺寸调参不当会让“过小的 tile 使 kernel launch 频繁、GPU 利用率下降”。工程上应把 $\\kappa$ 当作调参目标函数的一部分：在显存允许的前提下选尽量大的 tile，让 $\\kappa$ 接近 1，而不是一味追求最小显存。</p>\n<p>真正把解码时延从端到端关键路径上拿掉的是流水重叠。解码与下一请求的 DiT 采样跑在不同 stream 上，于是端到端时延近似为 <span class=\"formula\">$$T_{\\text{e2e}} \\approx \\max\\left(T_{\\text{DiT}},\\, T_{\\text{decode}}\\right) + T_{\\text{非重叠段}}$$</span>。只要 $T_{\\text{decode}}\\le T_{\\text{DiT}}$，解码就被完全隐藏在采样之后，SLO 关注的是端到端时延，此时解码不再是瓶颈。代价是两路并发争抢显存与带宽：解码的激活缓冲与 DiT 的 KV/权重同时驻留，显存预算要按两路峰值之和核算，而不是单路。具体 SLO 数值材料未给出，只能定性判断“解码部分被隐藏”。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-16\">十六 · halo 与加权融合的可实现形式</h3>\n<p>halo 的作用是让每个块的边界像素在解码器感受野内看到足够的上下文。设块在某一维的尺寸为 $s$，解码器在该维的有效感受野半径为 $r$，则 halo 宽度必须满足 <span class=\"formula\">$$h \\ge r$$</span>，否则块边界处的输出缺少真实邻居信息，融合再巧也补不回来。实际实现取 $h=r$ 或略大，并在块划分时让相邻块的重叠区宽度为 $2h$（每侧各 $h$）。重叠区的输出不能简单相加，否则亮度翻倍；用加权融合：<span class=\"formula\">$$O(x)=\\frac{\\sum_{k} w_k(x)\\,O_k(x)}{\\sum_{k} w_k(x)}$$</span>，其中 $w_k(x)$ 是第 $k$ 块在位置 $x$ 的权重，在块中心取 1，向边界单调衰减到 0。权重窗可选线性、余弦或平滑窗，关键是两块权重在重叠区互补，使分母恒为常数、无亮度跳变。</p>\n<p>伪代码落到可实现层面，核心是“切分—逐块解码—散射写回—融合”四步，且切分与写回都用同一套坐标映射，避免索引错位：</p>\n<ul>\n<li>输入 latent 张量形状 $[B,C,H,W]$，按 $(t_h,t_w)$ 网格切分，每块索引 $(i,j)$ 的 latent 范围为 $[i\\cdot t_h-h,\\ (i+1)\\cdot t_h+h]$ 并 clamp 到图边界，记录该块在图中的有效写回区间。</li>\n<li>对每块调用 VAE 解码器上采样，得到输出块；块内对应 halo 的部分只用于提供上下文，不写回。</li>\n<li>把输出块的有效区间散射到输出缓冲区的对应位置，同时按预计算的权重窗累加到权重缓冲与输出缓冲。</li>\n<li>全部块完成后做一次逐元素除法 $O \\leftarrow \\text{acc}/\\text{wsum}$，得到无缝输出。</li>\n</ul>\n<p>代价在这里很具体：权重缓冲与输出缓冲同为输出分辨率的三通道量级，是额外的显存项，必须计入 $M_{\\text{halo}}$ 的核算；逐块散射写回是零散的显存写，带宽效率低于整块连续写；halo 区被重复解码，算力开销按重叠比例上升。失败模式明确：halo 不足或融合参数不当，块边界出现接缝与亮度跳变，高分辨率图像伪影明显。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-17\">十七 · 通道维拼接与缓冲区布局</h3>\n<p>机制描述里“在通道维拼接”容易被误读成把各块输出沿通道堆叠。正确的理解是：每个块解码出的输出块在通道维上是完整的（与整图解码同通道数），拼接发生在空间维的散射写回，而“通道维”指的是输出缓冲区按 $[B,C,H_{\\text{out}},W_{\\text{out}}]$ 布局，各块把自己的 $C$ 个通道写进对应空间位置。这样做的工程好处是输出缓冲区只需一份，融合在通道内逐元素完成，不需要为每块保留独立输出再拼接，省掉一份与输出同尺寸的中间缓冲。</p>\n<p>缓冲区布局直接决定流水是否安全。latent 缓冲区由 DiT 采样写入，解码读取；输出缓冲区由解码写入，后续后处理读取。当解码与下一请求的 DiT 采样在不同 stream 上重叠时，必须用事件或屏障保证“解码读到的 latent 已写完”，并为每个请求分配独立的 latent 与输出缓冲，禁止跨请求复用同一块内存。否则会出现失败模式：stream 同步或显存缓冲区复用出错，解码读到未写完的 latent 或输出缓冲区竞争。显存代价是每请求多一份 latent 与输出缓冲，这与 batch 容量提升的收益要一起权衡——分块降低的是解码激活峰值，不是这些常驻缓冲。</p>\n<p>一个具体例子：高分辨率请求的 latent 写入后，切块解码逐块散射进输出缓冲，权重缓冲同步累加，最后一遍除法收尾；与此同时下一请求的 DiT 采样在另一 stream 上推进，两路各自持有独立缓冲，靠事件同步交接。这条链上任何一处缓冲复用错误都会表现为图像局部错位或亮度异常，而不是崩溃，因此调试时应在融合后加边界一致性检查。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-18\">十八 · 复杂度与调参的工程判断</h3>\n<p>把两条公式合起来看，分块解码的总代价可以写成 <span class=\"formula\">$$C_{\\text{total}} \\approx \\underbrace{\\frac{H\\cdot W}{n_{\\text{tile}}^2}C_{\\text{dec}}+M_{\\text{halo}}}_{\\text{显存}} + \\underbrace{\\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\kappa}_{\\text{时延}} + \\underbrace{\\text{launch}(n_{\\text{tile}}^2)}_{\\text{利用率}}$$</span>。三项对 $n_{\\text{tile}}$ 的依赖方向不同：显存第一项随块数下降、halo 项随块数上升；时延随块数下降但被 $\\kappa$ 拖住；launch 开销随块数线性上升。因此 tile 尺寸不是“越小越省显存越好”，而是在显存约束下取使 $\\kappa$ 与 launch 开销可接受的最大 tile。调参顺序应是：先按模型实测 $C_{\\text{dec}}$ 与感受野定 halo 宽度，再在显存预算内放大 tile 直到接近 OOM 边界，最后验证边界伪影与利用率。</p>\n<p>与相邻算法的边界要分清：整图一次性解码显存峰值高、易 OOM，本算法在解码内部做空间切块与流水重叠；扩散流水线分阶段服务把 VAE 解码拆为独立 stage，那是服务编排层面的切分，与本算法在解码器内部切块不是一回事，两者可以叠加但解决的是不同瓶颈。规模上限受 tile 尺寸与 halo 开销约束，halo 重叠增加显存与算力，分块 kernel 利用率低于整图解码，具体规模数值材料未给出。</p>\n<p>最后的工程判断落在 kernel 融合上：分块解码的 kernel 形状小、launch 频繁，是 $\\kappa$ 与利用率损失的主要来源。把切块解码中的逐层上采样、归一化与融合写回尽量融进少数几个 kernel，减少每块的 launch 次数与中间缓冲往返，是让 $\\kappa$ 逼近 1 的现实手段；在融合 kernel 到位之前，宁可放大 tile、少切几块，也不要为了省显存把块切到 launch 开销主导的区间。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-19\">十九 · 边界条件：halo 与 tile 的耦合代价</h3>\n<p>分块解码的收益并非无界。显存峰值由单 tile 激活与 halo 重叠区共同决定，而 halo 宽度必须覆盖 VAE 解码器中感受野最大的那一层——通常由若干级上采样卷积与残差块串联累积而成。设解码器在空间维的等效感受野半径为 $r$，则 halo 至少取 $r$ 才能保证块边界像素的输入上下文完整；halo 取小于 $r$ 时，边界像素在卷积中看到的邻域被截断，重叠区加权融合只能平滑亮度跳变，无法恢复丢失的高频结构，接缝表现为纹理断裂而非简单色差。这是分块方案最本质的失效条件：它不是调参问题，而是感受野与切块尺寸的结构性冲突。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}} + M_{\\text{halo}},\\quad T_{\\text{decode}} \\approx \\sum_{i} T_{\\text{tile},i} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$$</div>\n<p>式中 $C_{\\text{dec}}$ 是单像素在解码峰值时刻的激活字节数，$\\kappa&gt;1$ 是分块引入的额外开销系数，来源有三：halo 区被重复计算、块边界 kernel 形状不规整导致的有效算力损失、以及融合阶段的逐像素加权读写。$\\kappa$ 随 $n_{\\text{tile}}$ 减小而上升——块越小，halo 占比越高，launch 次数越多。因此存在一个由显存上限与利用率下限夹出的可行区间：tile 过大则 $M_{\\text{peak}}$ 回升触发 OOM，tile 过小则 $\\kappa$ 把解码时延推到流水重叠也遮不住的程度。工程上应先把 halo 钉死在感受野半径，再在剩余显存预算内取最大 tile，而不是反过来。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>边界接缝</td><td>halo &lt; 感受野半径，或融合权重非单调</td><td>画质返工，需整图重解</td></tr><tr><td>显存回升</td><td>tile 放大后 $M_{\\text{tile}}$ 逼近预算</td><td>batch 被迫下调，吞吐塌陷</td></tr><tr><td>利用率下降</td><td>tile 过小，launch 频繁</td><td>解码时延超出流水可隐藏窗口</td></tr><tr><td>缓冲区竞争</td><td>stream 同步缺失或缓冲复用过早</td><td>读到未写完 latent，输出错帧</td></tr></tbody></table>\n<p>流水重叠本身也带来正确性边界。解码 stream 与下一请求的 DiT 采样 stream 并发时，latent 缓冲区的写后读必须由事件显式同步；若复用同一输出缓冲区而未等融合 kernel 完成，会出现块间数据串扰。伪代码层面需保证：切分前对 latent 缓冲做一次记录事件，逐块解码的每个 tile 携带自己的 halo 索引区间，融合 kernel 只读取已完成的相邻块输出，输出缓冲按请求代际轮转而非原地复用。融合权重建议用与 halo 距离相关的单调窗函数，且窗宽与 halo 宽度绑定，避免出现权重和不为 1 的亮度漂移。</p>\n<h3 id=\"alg-vae-tiled-decode-sec-20\">二十 · 请求形态：什么样的解码请求值得分块</h3>\n<p>分块解码不是普适加速器，它是一张针对特定请求形态的处方。判断一个请求是否落在处方内，看三个量：latent 的空间尺寸 $H\\times W$、解码器通道宽度 $C_{\\text{dec}}$、以及服务端愿意为单请求预留的激活显存额度。整图解码的峰值激活随 $H\\cdot W$ 线性放大，当高分辨率 latent 送入 VAE 上采样时，单次激活峰值可达数十 GB 量级，这是分块机制的触发条件。反过来，若请求的 latent 尺寸小到整图解码峰值远低于显存水位，分块只会带来 halo 额外算力与小 kernel 的利用率损失，是纯负收益。</p>\n<p>因此负载配方的第一条判据是分辨率门槛而非请求数量。工程上可写成准入条件：设单卡可用于解码激活的显存预算为 $B_{\\text{act}}$，整图解码估算峰值为 $M_{\\text{full}}$，仅当 $M_{\\text{full}} &gt; B_{\\text{act}}$ 时才走分块路径；否则走整图解码。这条判据必须放在调度器入口而不是解码器内部，因为一旦进入分块路径，tile 尺寸、halo 宽度、输出缓冲区布局都已按分块形态分配，中途切换代价高于入口分流。</p>\n<p>第二条判据是长度分布。这里的“长度”指 latent 空间尺度而非序列长度：同一服务里往往并存低分辨率预览请求与高分辨率成片请求，两者峰值显存相差一个数量级以上。混合负载下若统一按高分档配置 batch，低分请求会被迫承受分块开销；若统一按低分档配置，高分请求直接 OOM。可行做法是按 latent 面积分档，每档绑定一组 tile 尺寸与 batch 上限，档内共享同一套缓冲区布局，档间不共享。分档边界应落在整图解码峰值刚好越过显存预算的位置，而不是按经验取整。</p>\n<p>具体例子：一个同时接受低分辨率草稿与高分辨率成片的推理服务，若把两类请求塞进同一连续批处理批次，调度器会按批内最大 latent 面积分配输出缓冲区，低分请求的显存占用被高分请求拉高，batch 容量被无谓压缩。按面积分档后，低分档可以维持更大的并发批，高分档以较小批换取不 OOM，整体吞吐反而上升。这就是负载配方与批调度耦合的地方：分块解码的 batch 上限不是常数，而是 tile 尺寸与 halo 显存的函数。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-21\">二十一 · 批大小与 tile 尺寸的耦合约束</h3>\n<p>批大小在分块解码里不是一个可以独立调的旋钮。单请求的解码激活峰值近似为 $M_{\\text{peak}} \\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}} + M_{\\text{halo}}$，其中 $n_{\\text{tile}}$ 是每维切块数，$M_{\\text{halo}}$ 是重叠区带来的额外显存。批内 $b$ 个请求同时解码时，激活占用按 $b$ 倍放大（输出缓冲区另计），于是可行批大小的上界由下式给出：</p>\n<div class=\"formula\">$$b_{\\max} \\approx \\left\\lfloor \\frac{B_{\\text{act}} - M_{\\text{buf}}}{M_{\\text{peak}}(n_{\\text{tile}})} \\right\\rfloor$$</div>\n<p>这个式子说明两件事。第一，$n_{\\text{tile}}$ 增大时 $M_{\\text{peak}}$ 下降，$b_{\\max}$ 上升，但 halo 开销与 kernel 数量同步上升，$T_{\\text{decode}} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$ 中的 $\\kappa$ 随切块变细而恶化，因为小形状 kernel 的 launch 频繁、GPU 利用率低于整图解码。第二，$M_{\\text{buf}}$ 是输出缓冲区，它不随分块缩小——输出始终是全分辨率张量，分块只压解码中间激活。这意味着在极高分辨率下，输出缓冲区本身可能成为新的显存瓶颈，此时继续缩小 tile 不再换来 batch 提升。</p>\n<p>工程判断因此是双目标而非单目标：在满足 $b_{\\max}\\ge 1$ 且不 OOM 的前提下，选使 $b_{\\max}\\cdot \\frac{1}{T_{\\text{decode}}(n_{\\text{tile}})}$ 最大的 $n_{\\text{tile}}$。这个乘积就是解码阶段的吞吐代理指标。切块过细时 $T_{\\text{decode}}$ 因 $\\kappa$ 恶化而上升，吞吐代理下降；切块过粗时 $b_{\\max}$ 掉到 1，并发消失，吞吐同样下降。最优点通常落在“刚好让批内多个请求的激活装进预算”的粗粒度一侧，而不是最细切块。</p>\n<p>具体例子：某高分档请求整图解码峰值达数十 GB，单卡预算远不能容纳，$b_{\\max}=1$ 时服务退化为串行解码，端到端时延被解码段主导。把 tile 切到使 $M_{\\text{peak}}$ 降到预算的几分之一后，$b_{\\max}$ 升到多个请求并行，虽然单请求解码因 halo 与 kernel 开销略慢，但批内并发把解码段摊薄，整体吞吐上升。这就是分块“batch 容量提升”的实际来源：不是单请求变快，而是单请求显存占用变小后换来了并发。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-22\">二十二 · 并发形态与流水重叠的负载前提</h3>\n<p>分块解码的时延收益有一半来自与 DiT 采样的流水重叠：解码与下一请求的采样在不同 stream 上并行，解码时延被隐藏。但这条收益有严格的负载前提——服务端必须同时存在“正在采样的请求”和“刚采样完待解码的请求”。若请求到达是严格串行的，即上一个请求解码完成后下一个才开始采样，流水重叠无从发生，$T_{\\text{decode}}$ 全额暴露在端到端时延里，分块只贡献了显存节省而没有贡献时延节省。</p>\n<p>因此并发配方要保证解码队列非空。设采样阶段平均耗时 $T_{\\text{samp}}$、解码阶段耗时 $T_{\\text{decode}}$，流水重叠能隐藏的解码量上限为 $T_{\\text{samp}}$；当 $T_{\\text{decode}} \\le T_{\\text{samp}}$ 时解码可被完全隐藏，端到端时延趋近采样时延；当 $T_{\\text{decode}} &gt; T_{\\text{samp}}$ 时，超出部分 $T_{\\text{decode}} - T_{\\text{samp}}$ 仍暴露。分块把 $T_{\\text{decode}}$ 压到接近 $T_{\\text{samp}}$ 的量级，正是为了让这个不等式成立。这也解释了为什么 tile 尺寸不能一味求细：$\\kappa$ 恶化会把 $T_{\\text{decode}}$ 推回 $T_{\\text{samp}}$ 之上，重叠收益消失。</p>\n<p>并发批的组织方式随之确定：解码 stream 上应维持至少一个待解码请求，采样 stream 上维持至少一个在采样请求，两者通过显存缓冲区交接。缓冲区复用是这里最脆弱的环节——若采样 stream 尚未把 latent 写完，解码 stream 就读走，会读到半成品 latent，输出出现整体性错误而非局部伪影；若输出缓冲区在融合完成前被下一请求复用，会出现块间竞争。工程上必须用事件同步而非固定延时来交接，且缓冲区按请求而非按 stream 分配。</p>\n<p>具体例子：连续批处理场景下，批内请求采样完成时间参差，先完成的请求进入解码队列，后完成的仍在采样，天然形成重叠。若调度器为了简化而等整批采样全部完成再统一解码，重叠窗口被抹平，分块解码退化为串行段，端到端时延回到 $T_{\\text{samp}} + T_{\\text{decode}}$。负载配方在这里的要求是：解码调度按请求粒度触发，不按批粒度同步。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-23\">二十三 · 负载不对时的失效形态</h3>\n<p>负载配方错配不会表现为崩溃，而表现为三类可观测的退化。第一类是分辨率错配：把分块路径用于低分辨率请求，halo 重叠与加权融合引入额外计算，块边界融合的算力占比上升，而显存本不紧张，收益为零、代价为正。第二类是并发错配：请求串行到达时流水重叠失效，$T_{\\text{decode}}$ 全额暴露，端到端时延不降反升，因为分块本身比整图解码慢（$\\kappa&gt;1$）。第三类是 tile 调参错配，这是最危险的一类。</p>\n<p>tile 尺寸调参不当有两个方向。过大时 $M_{\\text{peak}}$ 回升，批内激活重新逼近预算，触发 OOM 或被迫把 $b_{\\max}$ 压回 1，分块的意义被抵消；过小时 kernel 形状变小、launch 频繁，GPU 利用率低于整图解码，$T_{\\text{decode}}$ 被 $\\kappa$ 推高，解码段重新成为端到端瓶颈。更隐蔽的是 halo 参数不当：重叠区不足或加权融合参数不对，块边界出现接缝与亮度跳变，高分辨率图像伪影明显——这类失效不体现在延迟与吞吐指标上，只体现在输出质量上，监控若只看性能会漏掉。</p>\n<p>还有一类失效来自流水同步：解码与采样在不同 stream 上重叠时，若 stream 同步缺失或显存缓冲区复用出错，解码读到未写完的 latent，或输出缓冲区被并发写，结果是整幅输出错误而非局部接缝。这类错误的特征是随机性强、难以复现，且往往在高并发下才暴露。稳定性技巧上，重叠 halo 与加权融合只能抑制几何接缝，抑制不了同步错误；后者必须靠事件级依赖与缓冲区所有权转移来保证。</p>\n<p>具体例子：某服务把 tile 调得极细以追求最大 batch，结果 $b_{\\max}$ 确实上升，但单请求解码时间因小 kernel launch 频繁而显著变长，批内总解码时间不降，端到端时延反而恶化；同时 halo 融合参数未随 tile 变细而重调，块边界出现亮度跳变。这是典型的“指标看着好、体验看着差”的错配。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-24\">二十四 · 配方表与准入判据</h3>\n<p>把上述约束落成一张可执行的配方表，按 latent 面积分档给出 tile 粒度、batch 上限与流水策略。表中不填具体数值，因为 tile 尺寸需按模型调参，批大小受 tile 尺寸与 halo 显存约束且具体批大小未给出；填的是判据与相对关系。</p>\n<table class=\"mini\"><thead><tr><th>负载档</th><th>准入判据</th><th>tile 粒度</th><th>batch 上限</th><th>流水策略</th><th>主要风险</th></tr></thead><tbody>\n<tr><td>低分档</td><td>整图峰值低于激活预算</td><td>不分块</td><td>按显存与算力常规配置</td><td>无需解码流水</td><td>误入分块路径导致纯开销</td></tr>\n<tr><td>中分档</td><td>整图峰值略超预算</td><td>粗粒度，halo 占比小</td><td>由 $M_{\\text{peak}}$ 反推，追求 $b_{\\max}\\ge 2$</td><td>解码与采样重叠，按请求触发</td><td>tile 过大导致 OOM 回升</td></tr>\n<tr><td>高分档</td><td>整图峰值达数十 GB</td><td>中细粒度，需重调 halo 融合</td><td>受输出缓冲区 $M_{\\text{buf}}$ 约束</td><td>重叠 + 事件级缓冲区交接</td><td>$\\kappa$ 恶化、同步错误、接缝</td></tr>\n</tbody></table>\n<p>准入判据应写成调度器里的显式分支：先估算 $M_{\\text{full}}$，与 $B_{\\text{act}}$ 比较决定是否分块；分块后再用 $b_{\\max}$ 公式反推批上限；最后检查 $T_{\\text{decode}} \\le T_{\\text{samp}}$ 是否成立，不成立则回调 tile 粒度。这三步的顺序不能颠倒，因为 tile 粒度同时影响显存与时间，先定显存可行域再在域内选时间最优点，比先选时间再验显存稳健。</p>\n<p>配方表还要标注一条硬约束：输出缓冲区不随分块缩小。当 $M_{\\text{buf}}$ 本身逼近预算时，分块已无法通过缩小 tile 换取 batch，此时正确的动作是降分辨率档位或拆请求，而不是继续切细。这条约束常被忽略，因为工程上注意力都放在解码激活上，而输出张量是沉默的显存占用者。</p>\n<p>具体例子：高分档请求在 $M_{\\text{buf}}$ 约束下 $b_{\\max}$ 只能为 1，此时流水重叠仍可生效——单请求解码与下一请求采样重叠，端到端时延中解码段被部分隐藏，但吞吐不再随批增大。这说明分块解码在高分档的收益从“吞吐”转向“时延隐藏”，负载配方的目标函数要随档位切换。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-25\">二十五 · 工程判断的落点</h3>\n<p>负载配方的核心判断可以压缩成一句话：分块解码的收益来自显存换并发与流水换时延，两者都要求请求形态落在高分辨率、非串行到达、批内可并发的交集里；离开这个交集，halo 开销与 $\\kappa$ 恶化就是净损失。因此调度器入口的分档判据比解码器内部的 tile 调参更重要——前者决定要不要付这笔代价，后者只决定付得值不值。</p>\n<p>具体到实现，准入分支应基于对 $M_{\\text{full}}$ 的估算而非实测 OOM 回退。靠 OOM 回退来触发分块是事后补救：第一次高分请求已经失败，且回退路径上的缓冲区布局要重建，时延尖峰不可避免。前置估算可以用 latent 尺寸与 $C_{\\text{dec}}$ 直接算出量级，误差由安全系数吸收，这比运行时捕获分配失败稳健得多。</p>\n<p>最后一个工程落点是监控口径。分块解码的失效有一半不体现在延迟与吞吐上，而体现在输出质量与随机错误上，所以负载配方必须绑定质量侧的观测：块边界接缝检测、亮度跳变统计、以及流水交接处 latent 完整性的断言。只盯 $T_{\\text{decode}}$ 与 $b_{\\max}$ 的监控会漏掉 halo 参数错配与 stream 同步错误这两类最贵的失效。把质量观测与性能观测放在同一张面板上，负载配方才算闭环。</p>\n<h3 id=\"alg-vae-tiled-decode-sec-26\">二十六 · 硬件档位：按 tile 工作集而非整图峰值选卡</h3>\n<p>分块解码把显存需求从“整图上采样激活”改写成“单 tile 激活 + halo 开销”，因此选卡的判据不再是“能不能装下整图解码”，而是“单 tile 工作集能否与 DiT 采样共存于同一张卡”。工程上先算出单 tile 激活量级：给定 latent 高宽 $H\\cdot W$、切块数 $n_{\\text{tile}}^2$、解码器通道放大系数 $C_{\\text{dec}}$，峰值近似为</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}} + M_{\\text{halo}}$$</div>\n<p>这个式子决定了档位划分：当整图解码峰值达到数十 GB 时，单卡必须靠分块才能承载高分辨率请求；而一旦 $n_{\\text{tile}}$ 取大，$M_{\\text{peak}}$ 迅速落到单卡可容纳区间，档位选择就从“显存容量优先”转向“显存带宽与 kernel 发射效率优先”。原因是分块解码的 kernel 形状小、launch 频繁，GPU 利用率低于整图解码，此时瓶颈往往不是算力而是调度开销与显存带宽。判断方法很直接：把 $T_{\\text{decode}} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$ 中的 $\\kappa$ 当作实测标定系数，若 $\\kappa$ 明显大于 1，说明分块带来的额外 halo 计算与发射开销已经吃掉并行收益，该档位应优先换更高主频、更大 L2 的卡，而不是继续加显存。对 GB200/GB300 NVL72 这类机柜级系统，单卡显存不再是约束，约束转移到 NVLink 5 上的 latent 缓冲区搬运与跨卡 halo 交换，档位判断改为“每卡 tile 吞吐 × 卡数”是否覆盖解码队列。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-27\">二十七 · 并行拓扑：tile 内串行、tile 间与请求间两级并行</h3>\n<p>分块解码的并行结构有两层，不能混为一谈。第一层是 tile 间并行：不同 tile 之间没有数据依赖（除 halo 融合），可以把 $n_{\\text{tile}}^2$ 个块分给多个 SM 甚至多张卡同时解码，输出写入输出缓冲区的不同区域。第二层是请求间并行：解码与下一请求的 DiT 采样在不同 stream 上流水重叠，使解码时延被隐藏。拓扑设计的关键是把这两层映射到硬件：单卡内用多 stream 承载 tile 间并行与请求间流水，跨卡时按 tile 网格切分，让每张卡负责一个连续子区域，halo 重叠区通过 NVLink 交换而非回读全局显存。</p>\n<p>一个可复现的拓扑配方是：单机 8 卡，每卡 2 条 stream，stream A 跑当前请求的 tile 解码，stream B 跑下一请求的 DiT 采样；tile 网格按卡数整除切分，halo 区由相邻卡各算一半再在融合阶段合并，避免重复计算整条 halo。代价体现在通信量上：halo 宽度为 $w_h$ 时，跨卡交换的数据量为边界长度乘通道数乘 $w_h$，若切分过细，halo 占比上升，NVLink 带宽成为新瓶颈；若切分过粗，单卡 tile 工作集回升，显存重新吃紧。工程判断是让 halo 占单 tile 面积的比例控制在个位数百分比，用 $n_{\\text{tile}}$ 与卡数的乘积反推 tile 尺寸，而不是先定 tile 再定卡数。</p>\n<p>调度参数在这里与拓扑耦合：连续批处理把解码请求按 tile 队列而非按请求排队，一个长请求的多个 tile 可以与另一个短请求的 tile 交错发射，填满因 kernel 形状小而产生的发射空隙。这正是分块解码相对整图解码的额外收益——整图解码是一个大 kernel，批处理只能按请求粒度；分块后批处理粒度降到 tile，调度器可以用 tile 级队列把 GPU 利用率拉回可用区间。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-28\">二十八 · 量化方案：解码器权重量化与激活精度分层</h3>\n<p>VAE 解码器的量化与 DiT 主干不同：解码器是卷积/上采样结构，激活动态范围随 tile 内容变化，且 halo 融合对数值误差敏感。可复现的分层方案是权重侧用低精度（FP8 或 NVFP4 权重，配合 per-channel 缩放），激活侧保留较高精度（FP8 或 BF16），融合阶段的加权系数与重叠区累加用 FP32。理由是块边界接缝本质是相邻 tile 在同一像素上的数值差，若两侧 tile 用不同量化误差的激活计算，融合后会出现亮度跳变；把融合放在高精度累加器里，可以把量化噪声压到融合权重之下。</p>\n<p>量化的系统代价要按 tile 粒度核算：权重常驻显存，低精度权重直接降低每卡权重占用，释放出的显存可换成更大的 batch 或更大的 tile；激活低精度则降低单 tile 激活带宽，但分块解码的 kernel 形状小，带宽收益不如整图解码明显，收益更多体现在 L2 命中与融合 kernel 的读写量上。一个具体例子：当 $M_{\\text{peak}}$ 中 $M_{\\text{halo}}$ 占比不可忽略时，halo 区的激活若用 FP8 存储，融合时需要反量化再累加，反而增加一次读写；此时更优做法是 halo 区激活直接以 FP32 写入输出缓冲区，只在非重叠区用低精度，把量化收益留给占面积最大的 tile 内部。</p>\n<p>量化与 tile 尺寸存在联动：tile 越小，单 tile 激活越少，量化带来的绝对显存节省越小，而反量化与融合的固定开销占比越大。因此小 tile 配置下应优先量化权重而非激活；大 tile 配置下激活量化才有意义。这条判断不需要实验数字，由 $M_{\\text{peak}}$ 公式中两项的相对大小直接给出。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-29\">二十九 · KV 策略：解码阶段无 KV，缓冲区即状态</h3>\n<p>VAE 解码是前馈上采样，没有自回归键值缓存，因此“KV 策略”在本算法里指 latent 缓冲区与输出缓冲区的生命周期管理，而不是注意力缓存。可复现的策略是把 latent 缓冲区与输出缓冲区按请求预分配、按 tile 复用：DiT 采样完成后 latent 写入缓冲区，解码逐 tile 读取，输出写入输出缓冲区的对应偏移；请求结束后缓冲区回到池中，供下一请求复用。关键约束是流水重叠下的写后读顺序——解码与下一请求的 DiT 采样在不同 stream 上重叠时，若缓冲区复用出错，解码会读到未写完的 latent，或两个请求竞争同一输出缓冲区。</p>\n<p>工程做法是给每个缓冲区加 stream 级事件：DiT 采样 stream 在 latent 写完后记录事件，解码 stream 等待该事件再启动 tile 读取；输出缓冲区在融合完成后再释放。代价是事件同步引入的固定延迟，在 tile 数量多、单 tile 计算短时，同步开销占比上升，此时应把同一请求的多个 tile 合并为一次事件等待，而不是每 tile 一次。另一个代价是缓冲区池的容量：流水重叠要求至少两份 latent 缓冲区（当前解码请求 + 下一采样请求）与两份输出缓冲区，显存预算需按 $2\\times$ 缓冲区计，这部分开销与 $M_{\\text{peak}}$ 分开核算，不能混入 tile 工作集。</p>\n<p>halo 融合阶段对缓冲区的读写模式也有要求：重叠区被两个 tile 各写一次，融合需要读两次写一次，若输出缓冲区按 tile 分片存储，融合就是跨分片的局部操作；若按整图连续存储，融合是原地加权。后者显存访问更连续但需要额外的同步点，前者并行度更高但碎片化。选择依据是 tile 数量与融合 kernel 的发射成本，tile 多时选分片存储配合融合 kernel，tile 少时选连续存储减少同步。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-30\">三十 · 调度参数：tile 队列、stream 配比与融合时机</h3>\n<p>调度参数的核心是三组：tile 队列深度、stream 配比、融合触发时机。tile 队列深度决定连续批处理能否填满发射空隙——队列太浅，GPU 在 tile 之间空转；队列太深，输出缓冲区占用上升，与流水重叠的缓冲区预算冲突。可复现的起点是把队列深度设为“单卡并发 tile 数 × 2”，即每个 SM 组至少有两个待发射 tile，保证一个 tile 在算、一个在等数据。</p>\n<p>stream 配比指解码 stream 与 DiT 采样 stream 的数量比。分块解码的 tile 间并行度高，解码侧需要更多 stream 承载并发 tile；采样侧是单请求长任务，stream 少。配比失衡会导致一侧等待：解码 stream 过多而采样 stream 不足时，流水重叠退化为串行，解码时延不再被隐藏；反之采样 stream 过多会挤占解码的发射带宽。判断方法是看 $T_{\\text{decode}}$ 中 $\\kappa$ 的实测值随配比的变化，$\\kappa$ 下降到平台即配比合适。</p>\n<p>融合时机有两种：逐 tile 即时融合（每个 tile 写完就与已完成的邻居融合）与请求末统一融合（所有 tile 写完后一次性融合重叠区）。前者显存占用低、流水重叠友好，但融合 kernel 发射频繁，加剧小 kernel 问题；后者发射次数少、融合带宽利用率高，但需要保留全部 tile 输出直到最后，输出缓冲区峰值上升。工程判断是：当 $n_{\\text{tile}}^2$ 较大、单 tile 输出较小时选即时融合；当 tile 少而单 tile 输出大时选统一融合。无论哪种，融合 kernel 都应与上采样 kernel 融合为一次发射，这是分块解码在 Blackwell 上把 GPU 利用率拉回整图解码水平的关键手段——把“上采样 + 写缓冲区 + 加权累加”合成一个 kernel，消除 tile 间反复 launch 的开销。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-31\">三十一 · 可复现配置思路：从公式反推参数</h3>\n<p>把上述选择串成一条可复现的推导链，而不是给一组固定参数。第一步，用整图解码峰值确认必须分块：当整图峰值达数十 GB 时，$n_{\\text{tile}}$ 至少取到使 $M_{\\text{peak}}$ 落入单卡可容纳区间的值。第二步，由卡数与 tile 网格整除关系定 tile 尺寸，同时约束 halo 面积占比在个位数百分比。第三步，按 $M_{\\text{peak}}$ 中 $M_{\\text{halo}}$ 与 $M_{\\text{tile}}$ 的相对大小决定量化层级：halo 占比高则权重低精度、激活高精度；tile 占比高则激活也可低精度。第四步，按流水重叠需求分配缓冲区：至少两份 latent 与两份输出缓冲区，事件同步按请求粒度而非 tile 粒度。第五步，用 $\\kappa$ 标定调度参数：队列深度取并发 tile 数两倍，stream 配比以 $\\kappa$ 进入平台为准，融合时机按 tile 数量选择即时或统一。</p>\n<p>这条链的每一步都有可观测的失败信号：tile 过大时显存峰值回升触发 OOM；tile 过小时 kernel launch 频繁、GPU 利用率下降；halo 不足或融合权重不当出现块边界接缝与亮度跳变；stream 同步或缓冲区复用出错导致解码读到未写完的 latent。把这些信号作为配置回归的检查项，比固定一套参数更能适应不同分辨率与模型。最终落在具体机制上：分块解码的部署配方本质是把 $M_{\\text{peak}}$ 公式中的两个加数分别压到硬件档位与量化层级之内，再用 tile 级调度把被切碎的计算重新拼成高利用率的流水——tile 尺寸、量化分层、缓冲区预算、融合时机四者由同一个显存公式约束，任何一项单独调优都会在另一项上付出代价。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-32\">三十二 · 配方失效的三个断点：halo 预算、tile 下限与 stream 同步</h3>\n<p>这套配方的可复现性不取决于 tile 取多少，而取决于三条边界是否被显式建模。第一条是 halo 显存预算：分块后峰值满足 <span class=\"formula\">$$M_{\\text{peak}}\\approx M_{\\text{tile}}+M_{\\text{halo}}$$</span>，而 halo 随重叠宽度与通道数线性增长，因此“把 tile 调小以省显存”在 halo 占比升高后会失效——tile 缩小带来的激活下降被 halo 与融合缓冲吃掉，显存曲线出现谷底而非单调下降。工程上应把 halo 宽度按解码器感受野逐级上采样折算，而不是按经验取固定像素；融合权重表本身也要占显存，高分辨率下不可忽略。</p>\n<p>第二条是 tile 下限与 kernel 效率的冲突。分块解码的时延近似 <span class=\"formula\">$$T_{\\text{decode}} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$$</span>，其中 $\\kappa&gt;1$ 是 halo 重复计算与小形状 kernel launch 频繁带来的效率折损。tile 过小时 $\\kappa$ 迅速上升，GPU 利用率低于整图解码，解码虽被流水隐藏，却会挤占下一请求 DiT 采样的 stream 时间片，端到端时延反而回弹。判断阈值应看单 tile 的 kernel 占用是否仍能覆盖 launch 开销，而不是看显存是否够用。</p>\n<p>第三条是流水重叠的正确性代价。解码与下一请求采样分属不同 stream，latent 缓冲区必须按请求双缓冲或环形复用；若复用点在解码完成前释放，解码会读到未写完的 latent，输出缓冲区则出现跨请求竞争。这类错误不表现为崩溃，而是边界亮度跳变与局部接缝，与 halo 不足的伪影难以区分，排障成本高。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统表现</th><th>代价落点</th></tr></thead><tbody><tr><td>halo 宽度不足或融合参数不当</td><td>块边界接缝、亮度跳变</td><td>画质返工，需重跑解码</td></tr><tr><td>tile 过大</td><td>显存峰值回升触发 OOM</td><td>batch 被迫下调，吞吐塌陷</td></tr><tr><td>tile 过小</td><td>launch 频繁、$\\kappa$ 上升</td><td>GPU 利用率与流水隐藏收益同时下降</td></tr><tr><td>stream 同步或缓冲复用出错</td><td>读到未写完 latent、输出竞争</td><td>伪影随机出现，难以复现定位</td></tr></tbody></table>\n<p>因此配方应写成带守卫的配置：tile 尺寸由显存上限反解、halo 由感受野正推、缓冲区复用点绑定解码完成事件，并把 $\\kappa$ 作为回归指标而非事后观察。适用边界明确——整图解码峰值达数十 GB 的高分辨率 latent 场景收益最大；若分辨率低到整图解码本就不 OOM，分块只增加 halo 与 launch 开销，应直接走整图路径。</p>\n<h3 id=\"alg-vae-tiled-decode-sec-33\">三十三 · 显存账本：峰值、驻留与批容量的三角约束</h3>\n<p>分块解码的显存收益不是\"免费降峰值\"，而是把一笔整图激活的巨额支出拆成两栏账：单 tile 激活 $M_{\\text{tile}}$ 与 halo 重叠区额外驻留 $M_{\\text{halo}}$。前者随 tile 边长平方缩放，后者随 tile 周长线性增长——这个不对称是全部系统代价的根源。设 latent 空间尺寸 $H\\times W$、通道 $C_{\\text{lat}}$、解码器上采样倍率 $s$，则输出侧单 tile 激活约正比于 $(H/n_{\\text{tile}}\\cdot s)^2\\cdot C_{\\text{dec}}$，而 halo 环带面积约正比于 $4\\cdot(H/n_{\\text{tile}})\\cdot h_{\\text{halo}}\\cdot s^2$，其中 $h_{\\text{halo}}$ 为 halo 像素宽度。于是总峰值可写成</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\underbrace{\\left(\\frac{H}{n_{\\text{tile}}}\\cdot s\\right)^2 C_{\\text{dec}}}_{\\text{tile 激活}} + \\underbrace{4\\left(\\frac{H}{n_{\\text{tile}}}\\cdot s\\right) h_{\\text{halo}} s\\, C_{\\text{dec}}}_{\\text{halo 环带}} + M_{\\text{out}}$$</div>\n<p>关键在于 $M_{\\text{out}}$：输出缓冲区是整图尺寸的，它不随分块缩小。高分辨率请求下输出张量本身就可能占据数 GB 量级，这部分是刚性成本，分块无法压缩。因此\"分块把峰值降到单 tile 量级\"这句话只在激活项成立，输出项与模型权重项始终驻留。工程判断由此而来：当 $M_{\\text{out}}$ 已经逼近单卡可用显存的一半时，继续缩小 tile 的边际收益迅速衰减，而 kernel 效率损失却线性上升——这是规模上去后第一个崩点，不是 OOM，而是\"降了峰值却换不来 batch\"。批容量实际受限于 $\\lfloor (M_{\\text{free}}-M_{\\text{out}}-M_{\\text{weight}})/M_{\\text{peak}}^{\\text{per-req}}\\rfloor$，其中分母里 halo 项不可忽略。举例：一个 $4\\times$ 上采样的解码器在超高分辨率 latent 上整图解码激活可达数十 GB，分块后单请求峰值压到可容纳多请求的水平，但输出缓冲仍按整图分配，batch 提升幅度被输出项封顶。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-34\">三十四 · 带宽墙：halo 重复读取与写回放大</h3>\n<p>显存容量解决之后，紧接着暴露的是带宽。分块解码对 HBM 的访问模式有三重放大。第一重是 halo 重复读：相邻 tile 共享的环带被各自独立读入，重复读取量正比于 $n_{\\text{tile}}^2\\cdot 4h_{\\text{halo}}$，当 tile 切得越细，重复比例越高——这是\"小 tile 省显存、费带宽\"的直接来源。第二重是逐块写回输出缓冲区的非连续写：每个 tile 的输出写入整图缓冲的对应偏移，写事务在空间上跳跃，DRAM row 命中率下降。第三重是融合阶段的二次读写：重叠区加权融合需要把 halo 区域的输出再读一遍、加权、写回，等于对环带做了 read-modify-write。三者叠加，有效带宽需求可写成</p>\n<div class=\"formula\">$$B_{\\text{eff}} \\approx B_{\\text{ideal}}\\left(1 + \\frac{4h_{\\text{halo}}n_{\\text{tile}}^2}{HW}\\right)\\cdot\\eta_{\\text{row}}$$</div>\n<p>其中 $\\eta_{\\text{row}}&lt;1$ 刻画非连续写的 row 命中损失。这个式子说明：halo 宽度 $h_{\\text{halo}}$ 是带宽与伪影之间的旋钮，取小了接缝明显，取大了带宽成倍增长。更隐蔽的代价在融合 kernel：它必须在所有 tile 解码完成后才能对环带做加权，这意味着输出缓冲区在融合期间被同时读写，若与下一请求的解码流水重叠，两块 stream 会争抢同一段 HBM 带宽。规模上去后第二个崩点正是这里——不是算力不够，而是解码 kernel 与融合 kernel 的带宽需求叠加超过 HBM 可持续供给，表现为解码 step 时间被拉长、流水重叠失效。工程上应把融合并入 tile 解码的尾部写回（在写输出时直接按权重累加到重叠区），消除独立的 read-modify-write 趟次，代价是需要原子累加或按 tile 顺序串行化重叠区写。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-35\">三十五 · 通信与流水：跨 stream 同步的真实开销</h3>\n<p>解码与 DiT 采样在不同 stream 上重叠，听起来是零成本隐藏，实际存在三类同步代价。其一是事件依赖：解码必须等到 latent 缓冲区写完才能启动，采样侧必须等到输出缓冲区释放才能复用，两个 stream 之间靠 event 记录与等待串联，每次切换引入固定延迟，且该延迟随流水深度线性累积。其二是缓冲区复用竞争：若 latent 缓冲在请求间循环使用，解码读到未写完的 latent 就是正确性问题，必须靠双缓冲或 fence 隔离，双缓冲直接把 latent 驻留显存翻倍——这笔账常被忽略，却直接吃掉分块省下的显存。其三是多卡场景下的 tile 分发：当单请求 tile 数超过单卡并行能力，tile 需跨卡切分，halo 环带成为跨卡边界，融合需要跨卡交换边界数据。此时通信量正比于 tile 边界长度，即 $4\\cdot(H/n_{\\text{tile}})\\cdot h_{\\text{halo}}$ 每对相邻卡，走 NVLink 的时延虽低但不可忽略，且融合的加权需要边界两侧的完整数据，形成一次 all-to-all 式的边界交换。流水重叠的收益因此有条件：只有当解码时延显著大于同步开销与通信开销之和时，隐藏才成立。设单请求解码总时延 $T_{\\text{decode}}\\approx T_{\\text{full}}/n_{\\text{tile}}^2\\cdot\\kappa$（$\\kappa&gt;1$ 为小 kernel 效率损失因子），则流水有效吞吐增益约为</p>\n<div class=\"formula\">$$\\text{speedup}\\approx\\frac{T_{\\text{sample}}+T_{\\text{decode}}}{T_{\\text{sample}}+\\max(T_{\\text{decode}}-T_{\\text{sample}},0)+T_{\\text{sync}}}$$</div>\n<p>当 $T_{\\text{decode}}$ 被 tile 切分压到与 $T_{\\text{sync}}$ 同量级时，分子分母接近，流水形同虚设。这是规模上去后第三个崩点：tile 切得越细，单请求解码越快，但同步与 launch 开销占比越高，流水隐藏的绝对收益反而缩水。举例：一个请求的采样阶段耗时远大于解码阶段时，解码几乎完全被隐藏；但当采样被少步采样器压缩、解码仍按整图量级计算时，解码反而成为端到端主项，此时应增大 tile 而非减小，用更大的 tile 换更少的 launch 与同步。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-36\">三十六 · 功耗与利用率：小 kernel 的空转成本</h3>\n<p>分块解码的 kernel 形状小、launch 频繁，这个特征在功耗维度上表现为\"高静态功耗占比\"。GPU 在两次 launch 之间的调度间隙里 SM 处于低占用，时钟不降但计算单元空转，功耗并不随利用率线性下降。整图解码时一个大 kernel 长时间占满 SM，功耗曲线平滑且能量效率高；分块解码时每个 tile 的 kernel 只跑很短时间，launch 间隙与尾部 wave 的量化损失叠加，SM 占用率呈锯齿状。设单 tile kernel 有效计算时间为 $t_{\\text{comp}}$、launch 与调度开销为 $t_{\\text{ovh}}$，则 SM 时间利用率约 $t_{\\text{comp}}/(t_{\\text{comp}}+t_{\\text{ovh}})$，而功耗大致维持在接近峰值的水平，于是每焦耳有效计算量下降。规模上去后第四个崩点：当 tile 数达到数百量级，launch 开销累积成可观的墙钟时间，同时功耗不降，机架级功耗预算被无效计算占用。缓解手段是 kernel 融合——把逐 tile 的上采样、归一化、激活合并为单个 persistent kernel，用 grid-stride 循环在 kernel 内部遍历 tile，把 launch 次数从 $n_{\\text{tile}}^2$ 降到常数。代价是融合 kernel 内部需自行管理 tile 间的 halo 依赖与输出偏移，寄存器压力与 occupancy 需要重新平衡。在 GB200 NVL72 这类整机架部署中，功耗是机架级约束而非单卡约束，无效空转的功耗会被放大到整柜供电与散热预算上，因此融合 kernel 不只是性能优化，也是功耗治理手段。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-37\">三十七 · 尾延迟：分块带来的长尾与不均衡</h3>\n<p>吞吐是平均值，SLO 看的是尾延迟。分块解码引入两类长尾。第一类是 tile 间不均衡：边缘 tile 因图像边界处理、padding 与 halo 裁剪逻辑不同，计算量与中心 tile 不一致；若按固定顺序串行解码，最后一个 tile 的完成时间决定整请求完成时间，尾延迟由最慢 tile 决定而非平均 tile。第二类是流水错配的长尾：当解码与采样重叠，若某请求的采样异常快而解码排队，解码阶段的排队延迟会直接暴露在端到端时延上，形成 P99 尖峰。更麻烦的是输出缓冲区竞争：多个请求的解码共享输出缓冲池时，大分辨率请求占用整图缓冲，小请求被挤到等待队列，尾延迟随并发度非线性上升。设请求 $i$ 的解码完成时间为 $T_i = \\sum_{j} T_{\\text{tile},j}^{(i)}$，则端到端尾延迟近似为 $\\max_i(T_{\\text{sample},i}+T_i)$ 加上缓冲区等待项。工程判断：tile 调度应按\"最长 tile 优先\"排序以压缩 makespan，输出缓冲按请求分辨率分级池化以避免大请求饿死小请求；同时把融合写回与 tile 解码绑定，避免所有 tile 完成后才统一融合造成的尾部串行段。规模上去后第五个崩点正是尾延迟——平均吞吐仍在提升，但 P99 因 tile 不均衡与缓冲竞争持续恶化，SLO 先于容量触顶。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-38\">三十八 · 规模上限的判定顺序</h3>\n<p>把五个崩点按触发顺序排列，可以得到一条工程判定链。规模上升时，最先触发的是显存容量项中的输出缓冲刚性成本——它不随分块缩小，决定了 batch 上限的天花板；其次是 halo 带宽放大，当 tile 切细以省显存时，重复读取与融合读写把 HBM 带宽推过可持续阈值；第三是流水同步开销，tile 越细单请求解码越快，但 event 与双缓冲成本占比上升，隐藏收益递减；第四是 launch 与功耗，tile 数达数百量级后空转成本显性化；最后是尾延迟，tile 不均衡与缓冲竞争在平均指标仍健康时先击穿 SLO。判定顺序的意义在于：调参不应以\"峰值显存最小\"为唯一目标，而应求解一个受带宽、同步、功耗与尾延迟共同约束的 tile 尺寸。给定 halo 宽度与模型结构，存在一个使 $\\kappa$ 与 halo 开销乘积最小的 tile 边长区间；低于该区间，launch 与同步主导，高于该区间，显存回升触发 OOM。工程上应把 tile 尺寸、halo 宽度、双缓冲深度与融合 kernel 的 occupancy 作为一组联合参数在目标硬件上实测标定，而不是按显存公式单独外推——因为公式里的 $\\kappa$、$\\eta_{\\text{row}}$ 与 $t_{\\text{ovh}}$ 都是硬件与模型相关的隐参数，只能测不能算。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-39\">三十九 · 分块解码的规模天花板：显存、带宽与尾延迟谁先失守</h3>\n<p>分块把解码显存峰值压到单 tile 量级，但规模上去后最先失守的往往不是显存容量，而是<b>带宽与 kernel 利用率</b>。显存峰值满足 <span class=\"formula\">$$M_{\\text{peak}} \\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}} + M_{\\text{halo}}$$</span> 其中 $C_{\\text{dec}}$ 是单像素解码激活系数，$n_{\\text{tile}}$ 为每边切块数。$n_{\\text{tile}}$ 增大时主项按平方下降，但 $M_{\\text{halo}}$ 随块数线性上升——halo 重叠区在每块边界都要重算一遍上采样，重叠比例 $r_{\\text{halo}}$ 决定了这部分冗余算力。当 tile 小到一定程度，halo 开销反超主项收益，显存不再降而算力白烧，这就是调参不当导致“显存回升”的机理：过大的 tile 让主项重新逼近数十 GB 触发 OOM，过小的 tile 则让 kernel 形状碎化、launch 频繁，GPU 利用率低于整图解码。</p>\n<p>吞吐侧的关键代价是解码时延不再被完全隐藏。流水重叠成立的前提是解码时延 $T_{\\text{decode}}$ 不超过下一请求 DiT 采样的时间窗；一旦 tile 数增多、单块 kernel 又小，$T_{\\text{decode}} \\approx \\sum_i T_{\\text{tile},i} \\approx \\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$ 中的修正因子 $\\kappa&gt;1$ 来自 launch 开销与 halo 重算，解码可能反超采样窗口，流水退化为串行，尾延迟直接暴露在 SLO 上。此时融合 kernel（把切分、上采样、融合合并为少量大 launch）是唯一能把 $\\kappa$ 拉回 1 附近的手段，否则 batch 容量提升带来的吞吐收益会被尾延迟吃掉。</p>\n<table class=\"mini\"><thead><tr><th>规模上升时</th><th>先失守的资源</th><th>表现</th></tr></thead><tbody><tr><td>tile 过小</td><td>SM 利用率 / launch 开销</td><td>解码时延超采样窗口，流水失效</td></tr><tr><td>tile 过大</td><td>显存容量</td><td>峰值回升，OOM 或被迫降 batch</td></tr><tr><td>halo 比例偏高</td><td>算力与带宽</td><td>重叠区重复上采样，融合加权成瓶颈</td></tr><tr><td>stream 复用紧张</td><td>缓冲区一致性</td><td>读到未写完 latent，输出竞争</td></tr></tbody></table>\n<p>工程判断落在两处：其一，tile 尺寸必须按模型感受野与上采样倍率实测标定，使 $M_{\\text{halo}}$ 占比可控且 $\\kappa$ 不显著偏离 1；其二，解码与 DiT 采样跨 stream 重叠时，latent 写入与输出缓冲区的复用必须用事件同步而非隐式依赖，否则高并发下读到半写 latent 的竞争会以偶发伪影的形式出现，比 OOM 更难定位。规模上限因此不由显存单独决定，而由 halo 冗余、kernel 粒度与流水窗口三者的交集决定。</p>\n<h3 id=\"alg-vae-tiled-decode-sec-40\">四十 · 精度失败：halo 融合参数与边界接缝的定位</h3>\n<p>分块解码最先崩的往往不是显存，而是画质。块边界接缝在整图缩略图上几乎不可见，但放大到 2K 以上、或在下游检测/超分模型里就会放大成结构性伪影。根因是 halo 重叠区的加权融合权重与 tile 内有效区不一致：当 halo 宽度小于 VAE 解码器的有效感受野，边界处的卷积/上采样采样点缺失上下文，融合权重再平滑也补不回信息。诊断方法不是肉眼看图，而是在输出缓冲区上做差分探针：对同一 latent 分别跑整图解码（离线、小 batch、允许慢）与分块解码，逐像素求差，把差值按 tile 网格聚合，若误差能量集中在 tile 边界一圈，即判定为 halo 不足或融合核参数错。</p>\n<div class=\"formula\">$$\\epsilon_{\\text{seam}}=\\frac{1}{|\\partial\\Omega|}\\sum_{x\\in\\partial\\Omega}\\left|D_{\\text{full}}(x)-D_{\\text{tile}}(x)\\right|,\\quad \\epsilon_{\\text{inner}}=\\frac{1}{|\\Omega\\setminus\\partial\\Omega|}\\sum_{x\\notin\\partial\\Omega}\\left|D_{\\text{full}}(x)-D_{\\text{tile}}(x)\\right|$$</div>\n<p>工程判据是 $\\epsilon_{\\text{seam}}/\\epsilon_{\\text{inner}}$ 的比值，正常应接近 1；显著大于 1 就说明边界处理有问题。代价上，整图参考解码本身可能触发数十 GB 峰值，所以这条探针只能在小分辨率或离线回归集上跑，不能进在线链路。另一个精度陷阱是数值精度混用：若 tile 内用 FP8/NVFP4 而融合在 FP32 做，量化误差在重叠区被加权放大，表现为边界亮度跳变而非高频接缝。定位方式是固定 latent、切换 tile 内精度档位重跑差分，看 $\\epsilon_{\\text{seam}}$ 是否随精度档位单调变化。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-41\">四十一 · OOM 复发：tile 尺寸与 halo 的显存账</h3>\n<p>分块解码把峰值压到单 tile 量级，但 OOM 仍会复发，且复发点常常不在解码本身。显存账要按 $M_{\\text{peak}}\\approx M_{\\text{tile}}+M_{\\text{halo}}$ 逐项拆：$M_{\\text{tile}}$ 随 tile 边长平方增长，$M_{\\text{halo}}$ 随 halo 宽度与 tile 周长增长；此外输出缓冲区若按整图尺寸预分配，等于把整图激活又留了一份。典型复发场景是调大 tile 追求 GPU 利用率，tile 边长翻倍使 $M_{\\text{tile}}$ 变为四倍，叠加 halo 与输出缓冲区后重新顶到上限；另一场景是 batch 扩容时按“分块后省了显存”线性外推 batch，忽略了每请求仍各有一份输出缓冲区与流水重叠所需的双缓冲。</p>\n<ul>\n<li>监控项：每 step 的 <code>torch.cuda.max_memory_allocated</code> 与 reserved 之差（碎片指标）、单 tile 激活峰值、输出缓冲区占用、流水双缓冲份数。</li>\n<li>诊断顺序：先确认峰值出现在解码 kernel 还是融合 kernel；再把 tile 尺寸减半看峰值是否近似四分之一，若不是则瓶颈在输出缓冲区或双缓冲而非 tile 激活。</li>\n<li>回滚动作：把 tile 尺寸回退到上一个通过回归的档位，同时把 batch 回退一档，二者不要同时调，否则无法归因。</li>\n</ul>\n<p>代价上，tile 过小会让 kernel launch 频繁、GPU 利用率低于整图解码，吞吐下降；tile 过大则显存峰值回升。这个权衡没有解析最优解，只能靠回归集标定，并把标定结果写进部署配置而不是运行时自适应，避免抖动。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-42\">四十二 · 批抖动与路由不均：流水重叠下的排队形态</h3>\n<p>解码与 DiT 采样在不同 stream 上流水重叠后，系统从“串行两段”变成“两段并发”，批形态随之改变。抖动来源有三类：请求分辨率分布不均导致 tile 数差异大，同一 batch 内各请求的解码工作量相差数倍；stream 同步点设置不当，使解码等待采样完成、采样又等待解码让出缓冲区，形成互相阻塞；输出缓冲区复用冲突，多个请求争抢同一块缓冲导致隐式串行。路由不均则出现在多副本部署：按请求数轮询会把高分辨率请求集中打到某副本，而该副本的 tile 队列深度暴涨，尾延迟被单副本拖长。</p>\n<div class=\"formula\">$$T_{\\text{e2e}}\\approx \\max\\left(T_{\\text{sample}},\\,T_{\\text{decode}}\\right)+T_{\\text{sync}},\\quad \\text{jitter}=\\operatorname{std}\\left(T_{\\text{e2e}}\\right)/\\operatorname{mean}\\left(T_{\\text{e2e}}\\right)$$</div>\n<p>诊断上，按请求打点记录 $T_{\\text{sample}}$、$T_{\\text{decode}}$、$T_{\\text{sync}}$ 三段，若 jitter 主要来自 $T_{\\text{sync}}$ 则是同步/缓冲问题；若来自 $T_{\\text{decode}}$ 的方差则是 tile 数与 batch 组合问题。路由侧要按“预估 tile 数”而非请求数做负载均衡，预估可用 latent 分辨率与 tile 尺寸直接算出，不需要模型推理。代价是：为压 jitter 而限制单 batch 内分辨率跨度，会降低 batch 填充率、牺牲吞吐；不限制则尾延迟尖刺频发，SLO 违约集中在高分辨率长尾请求上。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-43\">四十三 · 尾延迟尖刺：从 tile 队列深度到融合 kernel</h3>\n<p>尾延迟尖刺的形态是 P99 远高于 P50，而均值正常。分块解码的尖刺通常来自三个具体机制：其一，融合 kernel 在重叠区做加权，若融合按 tile 串行执行且未与解码重叠，最后一块的融合成为关键路径；其二，tile 队列深度超过阈值后，调度器把多个请求的 tile 交错发射，单请求的 tile 完成时间被拉长，端到端时延出现阶跃；其三，显存碎片使某次 tile 分配触发同步回收，单次尖刺可达毫秒级但足以击穿 SLO。诊断要把 P99 请求的 tile 级时间线拉出来，看尖刺落在解码、融合还是分配上。</p>\n<table class=\"mini\"><thead><tr><th>尖刺位置</th><th>典型成因</th><th>观测信号</th><th>处置</th></tr></thead><tbody><tr><td>解码 kernel</td><td>tile 尺寸过大、利用率低</td><td>单 tile 耗时方差大</td><td>回退 tile 档位</td></tr><tr><td>融合 kernel</td><td>串行融合、未重叠</td><td>末块融合占关键路径</td><td>融合并入解码 stream</td></tr><tr><td>显存分配</td><td>碎片、双缓冲不足</td><td>alloc 同步等待</td><td>预分配输出缓冲池</td></tr><tr><td>stream 同步</td><td>同步点过密</td><td>$T_{\\text{sync}}$ 方差大</td><td>放宽同步粒度</td></tr></tbody></table>\n<p>代价判断：把融合并入解码 stream 能削掉末块关键路径，但融合与解码争用 SM，单 tile 解码变慢，吞吐略降；预分配缓冲池消除分配尖刺，但常驻显存上升，挤压 batch 容量。两者都是“用吞吐/显存换尾延迟”的交易，需按 SLO 的 P99 约束而非均值来选。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-44\">四十四 · 监控与回滚：可观测项与灰度策略</h3>\n<p>监控要覆盖三层：请求层（端到端时延分位、tile 数、分辨率分布）、算法层（$\\epsilon_{\\text{seam}}$ 回归探针、单 tile 激活峰值、融合耗时占比）、系统层（显存 reserved/allocated、stream 同步等待、kernel launch 频次）。其中 $\\epsilon_{\\text{seam}}$ 只能离线跑，在线用轻量代理：对输出做块边界梯度能量统计，边界一圈的高频能量突增即为接缝嫌疑。回滚策略要按失败模式分档，而不是整体回退到整图解码——整图解码在高分辨率下直接 OOM，回滚它等于放弃服务。</p>\n<ul>\n<li>精度类失败：回滚 halo 宽度与融合权重到上一标定档，tile 尺寸不动，避免同时改变两个变量。</li>\n<li>OOM 类失败：先回滚 batch 一档，仍复发再回滚 tile 尺寸一档，两级回滚分开灰度。</li>\n<li>抖动/尾延迟类失败：回滚 stream 同步粒度与缓冲池配置，路由侧切回按 tile 数均衡。</li>\n<li>灰度判据：新配置先在低分辨率流量上跑，$\\epsilon_{\\text{seam}}$ 与 P99 同时达标才放量到高分辨率。</li>\n</ul>\n<p>回滚本身有代价：配置切换需要排空在途请求，排空期间该副本吞吐为零；若回滚频繁，说明标定档位与真实负载分布脱节，应把负载配方中的分辨率分布纳入标定回归集，而不是在运行时反复试错。工程判断上，分块解码的稳定性不取决于单点最优参数，而取决于“参数档位—负载分布—SLO”三者绑定的标定表，运行时只做档位选择，不做参数搜索。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-45\">四十五 · 边界之外：分块解码的五类失效与可回滚的观测面</h3>\n<p>分块解码把显存峰值压到单 tile 量级，代价是把整图解码的单一失败点拆成了五个互相耦合的失败面：伪影、OOM 回潮、批抖动、路由不均、尾延迟尖刺。诊断的第一原则是分清“参数错”与“资源错”。halo 不足或融合权重失配属于参数错，表现为块边界接缝与亮度跳变，在高分辨率输出上尤其刺眼；此时显存曲线是平的，吞吐也正常，唯一异常是画质指标。反之，tile 调大导致 $M_{\\text{peak}}\\approx M_{\\text{tile}}+M_{\\text{halo}}$ 回升越过显存水位，属于资源错，表现为 OOM 或被迫降 batch，画质却毫无异常。两类故障的监控通道必须分开：前者靠离线或抽样的边界一致性校验（沿接缝取梯度与均值差），后者靠显存水位与分配失败计数。把两者混在一个告警里，回滚就会打错方向。</p>\n<p>批抖动与路由不均同源。分块后 batch 容量提升，但每个请求的 tile 数随 latent 分辨率变化，调度器看到的是“请求数”而非“tile 工作量”，于是同一 batch 内可能出现长短悬殊的 tile 队列，短请求等长请求，形成批抖动；若按请求做亲和路由，高分辨率请求集中落到少数副本，就会出现路由不均——那些副本的 tile 队列持续饱和，其余副本空转。诊断量应取 tile 级而非请求级：每副本的 tile 排队长度、tile 平均驻留时间、以及 $T_{\\text{decode}}\\approx\\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$ 中 $\\kappa$ 的实测漂移。$\\kappa$ 是 halo 重叠与 kernel launch 开销的综合放大系数，它一旦随负载上升而漂移，说明小形状 kernel 的 launch 频率已经压过计算本身，此时加副本无用，该做的是 kernel 融合或调大 tile。</p>\n<p>尾延迟尖刺最隐蔽，来源是流水重叠的同步缺陷。解码与下一请求的 DiT 采样跑在不同 stream 上，共用 latent 与输出缓冲区；若缓冲区复用缺少事件栅栏，解码可能读到尚未写完的 latent，或两个 stream 竞争同一输出区。这类错误不产生稳定报错，只在负载高、复用频繁时以尖刺形式出现，p99 突然抬升而均值不动。监控上应对每条 stream 打事件时间戳，记录“latent 写完—解码启动”的间隔与“解码完成—缓冲区回收”的间隔，任一间隔出现负值或异常收缩即为同步缺陷信号。回滚策略按代价排序：先降 tile 尺寸并恢复整图解码路径作为兜底（显存换稳定），再回退融合 kernel 版本，最后才动流水重叠开关——关掉重叠会直接暴露解码时延，是代价最大的一步。下表给出失效面与首选动作的对应。</p>\n<table class=\"mini\"><thead><tr><th>失效面</th><th>可观测信号</th><th>首选动作</th><th>系统代价</th></tr></thead><tbody><tr><td>边界伪影</td><td>接缝梯度/均值差超阈</td><td>加大 halo、重标融合权重</td><td>显存与算力上升，$\\kappa$ 增大</td></tr><tr><td>OOM 回潮</td><td>显存水位贴顶、分配失败</td><td>缩 tile 或降 batch</td><td>吞吐下降、launch 更频繁</td></tr><tr><td>批抖动</td><td>tile 驻留时间方差大</td><td>改 tile 级调度与配额</td><td>调度复杂度上升</td></tr><tr><td>路由不均</td><td>副本 tile 队列长度偏斜</td><td>按 tile 工作量而非请求数路由</td><td>路由表维护开销</td></tr><tr><td>尾延迟尖刺</td><td>stream 事件间隔异常</td><td>补事件栅栏、隔离缓冲区</td><td>重叠度下降，解码时延部分暴露</td></tr></tbody></table>\n<p>工程判断落在一条线上：分块解码的稳定性不取决于 tile 多大，而取决于 tile 尺寸、halo 宽度与融合 kernel 三者是否被当作一个整体版本化。任何一项单独热调都会破坏另两项的假设——调大 halo 而不重编融合 kernel，边界权重就错位；换融合 kernel 而不重测 $\\kappa$，容量规划就失真。因此监控面必须绑定版本号，回滚以“参数组”为单位而非单参数，且整图解码路径要常备为可切换的兜底分支，其显存代价在容量规划中预先预留，不能等到 OOM 才临时腾挪。</p>\n<h3 id=\"alg-vae-tiled-decode-sec-46\">四十六 · 对照轴：显存峰值、kernel 粒度与流水位置</h3>\n<p>把 VAE 分块解码放回同族算法谱系里，选择依据不是“谁更先进”，而是三条正交的轴：显存峰值由谁承担、解码 kernel 的形状是否被切碎、解码在流水中的位置。整图一次性解码把峰值压在单次上采样激活上，公式上就是 $M_{\\text{peak}}\\approx M_{\\text{full}}$，高分辨率 latent 下单次激活可达数十 GB，直接决定 batch 上限；分块解码把同一量改写为 $$M_{\\text{peak}}\\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}} + M_{\\text{halo}}$$，峰值随 $n_{\\text{tile}}^2$ 反比下降，代价是 halo 的额外显存与算力。而阶段级扩散服务走的是另一条路：它不改变解码内部的显存形状，只把 VAE 解码拆成独立 stage，用资源隔离与队列解耦换取流水弹性。三者不是互斥替代，而是分别回答“峰值怎么降”“kernel 怎么保”“流水怎么排”。选型时先问一句：瓶颈是显存墙、GPU 利用率，还是阶段间排空——答案不同，落点就不同。</p>\n<p>具体到工程判断：当一个请求的 latent 分辨率使整图解码激活逼近单卡剩余显存时，分块是唯一不需要改模型结构的降峰手段；当分辨率不高、整图解码的 kernel 形状饱满且 GPU 利用率已经接近饱和时，引入分块只会把大 kernel 切成小 launch，收益为负。阶段级服务则适用于解码与采样资源需求差异大、需要独立扩缩容的部署，但它对单请求显存峰值无能为力——峰值仍在 stage 内部。这条界线必须在决策表里写清楚，否则会出现“上了分离式部署却仍然 OOM”的典型误配。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-47\">四十七 · 决策表：四种形态的适用条件</h3>\n<p>下表把整图解码、分块解码、分块+流水重叠、阶段级分离四者放在同一张表里对照，列的是可判定的条件而非倾向性描述。</p>\n<table class=\"mini\"><thead><tr><th>形态</th><th>显存峰值</th><th>GPU 利用率</th><th>适用条件</th><th>不适用信号</th></tr></thead><tbody>\n<tr><td>整图一次性解码</td><td>$M_{\\text{full}}$，可达数十 GB</td><td>高，kernel 形状饱满</td><td>latent 分辨率中等、单卡余量充足、batch 不受显存约束</td><td>出现 OOM 或被迫降 batch</td></tr>\n<tr><td>分块解码（无重叠流水）</td><td>单 tile 量级 + halo</td><td>偏低，launch 频繁</td><td>高分辨率请求、显存是硬约束、解码不与采样并发</td><td>端到端时延中解码占比高且无法隐藏</td></tr>\n<tr><td>分块 + 采样/解码流水重叠</td><td>单 tile 量级 + 双缓冲</td><td>中等，两 stream 交替填充</td><td>解码时延需被隐藏、采样与解码可并发、缓冲区可复用</td><td>stream 同步复杂、缓冲区竞争风险高</td></tr>\n<tr><td>阶段级分离服务</td><td>stage 内部仍为整图峰值</td><td>按 stage 独立调节</td><td>解码与采样资源画像差异大、需独立扩缩容</td><td>单请求峰值仍是瓶颈、跨 stage 传输开销显著</td></tr>\n</tbody></table>\n<p>读表的关键在于后两列：分块与流水解决的是单请求内部的峰值与隐藏，阶段分离解决的是集群层面的资源配比。一个常见误判是把“解码慢”直接归因到需要阶段分离，而实际瓶颈是整图解码的显存峰值压低了 batch 容量——此时分块提升的是并发度而非单请求时延。反过来，若单请求时延中解码占比高且 batch 已足够，分块只能降峰不能降时延，必须叠加流水重叠才有效。决策顺序应当是：先判显存是否为约束，再判解码是否可被隐藏，最后才判是否需要跨 stage 的资源隔离。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-48\">四十八 · 与特征缓存、块级跳步的边界</h3>\n<p>同族里最容易混淆的是特征缓存与块级跳步：它们同样作用于扩散解码链路，但作用对象是“跨请求/跨步的重复计算”，而分块解码作用对象是“单次解码内的空间切分”。特征缓存命中时直接复用已算出的中间特征，省掉的是整段计算；块级跳步在采样步之间跳过部分块的更新，省掉的是时间维上的冗余。二者都不改变单次解码的激活峰值形状——缓存命中失败时仍要跑一次完整解码，峰值照旧。因此当 OOM 是主要矛盾时，缓存与跳步不能替代分块；当算力是主要矛盾、显存有余量时，分块的 kernel 切碎反而拖累利用率，此时应优先缓存与跳步。</p>\n<p>代价侧要算清楚：缓存引入显存占用与命中率波动，跳步引入质量损失与步间一致性风险，分块引入 halo 算力与边界伪影风险。三者可以叠加，但叠加顺序影响收益——先分块把峰值压到可容纳缓存的程度，再启用特征缓存，才不至于缓存本身把显存推回 OOM 边缘。一个具体例子：高分辨率请求在整图解码下峰值数十 GB，batch 被迫降到 1，此时缓存根本无处存放；分块把峰值降到单 tile 量级后，剩余显存才够容纳跨请求特征缓存，两者形成互补而非竞争。这条依赖关系应写进容量规划，而不是在调参时临时发现。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-49\">四十九 · 与混合精度分块、FP8/NVFP4 路径的取舍</h3>\n<p>量化路径与分块路径都声称“降显存”，但降的是不同对象：NVFP4/FP8 降的是权重与激活的位宽，分块降的是同时驻留的激活面积。二者相乘而非相加——分块后单 tile 激活本已很小，再叠加低精度量化的收益边际递减，而量化引入的数值误差在 halo 融合处会被放大：重叠区加权融合对两侧数值做线性组合，若两侧来自不同精度路径或不同舍入，接缝处的亮度跳变风险上升。工程判断是：当分块已经把峰值压到安全区，优先保解码精度而非继续压位宽；当分块受 tile 尺寸下限约束（过小则 launch 频繁、利用率崩）而峰值仍不够低时，才用低精度换空间。</p>\n<p>公式上可以把两条路径的峰值写成乘性关系：分块因子 $n_{\\text{tile}}^2$ 与位宽因子 $b$ 共同决定 $$M_{\\text{peak}}\\approx \\frac{H\\cdot W}{n_{\\text{tile}}^2}\\cdot C_{\\text{dec}}(b) + M_{\\text{halo}}$$，其中 $C_{\\text{dec}}(b)$ 随位宽下降。但 $M_{\\text{halo}}$ 不随位宽缩小，halo 重叠区的显存与算力是分块路径的固定税。因此在小 tile 情形下，halo 占比上升，量化收益被稀释；在大 tile 情形下，量化收益更明显但峰值回落有限。这条非线性关系决定了“先分块还是先量化”没有统一答案，必须按 tile 尺寸与 halo 比例实测后定。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-50\">五十 · 与阶段级服务流水的组合与冲突</h3>\n<p>分块解码与阶段级分离可以组合，但组合点在流水边界：分块发生在解码 stage 内部，阶段分离发生在 stage 之间。组合的正确形态是解码 stage 内部按 tile 逐块执行、stage 之间用队列传递 latent 与输出缓冲；错误形态是把 tile 当作独立 stage 拆出去，导致跨 stage 传输次数随 $n_{\\text{tile}}^2$ 增长，通信开销吞掉分块收益。判据很直接：若 tile 数量大、单 tile 计算量小，跨 stage 传输的固定开销会超过计算本身，此时应保持 tile 在 stage 内闭环。</p>\n<p>冲突点在于缓冲区所有权。分块解码要求输出缓冲区按 tile 位置写入并做重叠区融合，阶段分离则要求 stage 间缓冲由框架统一管理；两者叠加时，若融合在解码 stage 内完成，输出缓冲需等全部 tile 写完才可交付下游，流水重叠窗口被压缩；若把融合推到下游 stage，则下游需理解 halo 语义，耦合度上升。工程上更稳的做法是融合在解码 stage 内闭环、下游只接收完整输出，用双缓冲换取 stage 间的解耦。代价是解码 stage 的显存占用翻倍（双缓冲），这与分块降峰的初衷部分抵消，需按剩余显存余量决定缓冲深度。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-51\">五十一 · 选型判据的落地：三个可测信号</h3>\n<p>把决策表压缩成三个可测信号，避免选型停留在定性讨论。第一，整图解码的激活峰值与单卡剩余显存之比：接近 1 即显存墙成立，分块优先；远小于 1 则分块无必要。第二，解码 kernel 的平均占用与 launch 密度：整图解码 kernel 形状饱满、利用率高，分块后形状变小、launch 频繁，若实测利用率下降超过收益，应改用融合 kernel 或退回整图。第三，解码时延在端到端时延中的占比与可隐藏性：占比高且采样与解码可并发，则流水重叠必要；占比低则分块只为降峰，不必引入双缓冲复杂度。</p>\n<p>三个信号共同决定落点：显存墙成立且解码可隐藏 → 分块+流水重叠；显存墙成立但解码不可隐藏 → 分块+融合 kernel，优先保利用率；显存墙不成立但算力冗余 → 缓存与跳步；单请求峰值非瓶颈而集群资源配比失衡 → 阶段级分离。每个信号都对应一个具体机制而非倾向：显存比对应 $M_{\\text{peak}}$ 公式中的 $n_{\\text{tile}}$ 选择，利用率对应 halo 与 kernel 融合的取舍，时延占比对应 stream 重叠的窗口设计。选型的终点不是挑一个算法名，而是把这三个信号测出来，再让 tile 尺寸、halo 宽度、缓冲深度这三个旋钮各自落到可解释的位置上。</p>\n\n<h3 id=\"alg-vae-tiled-decode-sec-52\">五十二 · 分块解码的选型边界：三条路线的决策表</h3>\n<p>与分块解码并列的相邻路线有两条：整图一次性解码，以及把 VAE 解码拆成独立 stage 的扩散流水线分阶段服务。三者的差别不在数学，而在显存峰值落在哪里、流水重叠发生在哪一层。整图解码把整张 latent 一次上采样，激活峰值随 $H\\cdot W$ 线性增长，高分辨率下可达数十 GB，直接触发 OOM 或被迫降 batch；分块解码把峰值压到 $M_{\\text{peak}}\\approx M_{\\text{tile}}+M_{\\text{halo}}$，代价是 halo 重叠带来的额外算力与融合伪影风险；分阶段服务则把解码整体外移为一个 stage，跨请求做流水，但单请求内解码仍是整图，显存峰值并未下降。选型的第一判据因此是：显存峰值是否已成为瓶颈。若整图解码在目标分辨率与 batch 下仍有余量，整图路线的 kernel 形状大、launch 少、GPU 利用率最高，没有理由分块。</p>\n<p>第二判据是解码时延能否被隐藏。分块解码的真正收益不只是省显存，而是让解码与下一请求的 DiT 采样在不同 stream 上重叠，使 $T_{\\text{decode}}\\approx\\frac{T_{\\text{full}}}{n_{\\text{tile}}^2}\\cdot\\kappa$ 中的 $\\kappa$ 被采样时间吸收；分阶段服务把重叠放在请求之间，适合解码耗时占比高、请求流稳定的场景。两者可以叠加，但 stream 同步与显存缓冲区复用必须严格，否则解码会读到未写完的 latent 或输出缓冲区竞争，这是分块路线最典型的失效模式。</p>\n<table class=\"mini\"><thead><tr><th>路线</th><th>显存峰值</th><th>重叠层级</th><th>适用条件</th><th>主要失效</th></tr></thead><tbody><tr><td>整图解码</td><td>随 $H\\cdot W$ 增长，可达数十 GB</td><td>无</td><td>分辨率适中、batch 有余量</td><td>OOM、被迫降 batch</td></tr><tr><td>分块解码</td><td>$M_{\\text{tile}}+M_{\\text{halo}}$</td><td>解码与下一请求采样</td><td>高分辨率、整图峰值数十 GB</td><td>接缝伪影、tile 调参失当</td></tr><tr><td>分阶段服务</td><td>整图量级</td><td>请求间 stage 流水</td><td>解码耗占比高、请求流稳定</td><td>单请求峰值未降</td></tr></tbody></table>\n<p>第三判据是 tile 尺寸的可调空间。halo 重叠区不足或加权融合参数不当，块边界会出现接缝与亮度跳变；tile 过大则显存峰值回升触发 OOM，tile 过小则 kernel 形状小、launch 频繁，GPU 利用率低于整图解码，需融合 kernel 才能追平。规模上限由此受 tile 尺寸与 halo 开销双重约束：halo 同时增加显存与算力，分块收益随 tile 缩小而递减。工程判断是——当整图峰值逼近显存容量、且请求以高分辨率为主时选分块；当解码耗时可被请求间流水吸收且单请求峰值可控时选分阶段；两者都不满足时保留整图并靠 batch 调度消化。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2021 · 视频与流式生成推理</td></tr><tr><td>解决什么</td><td>高分辨率 latent 送入 VAE 解码时，单次上采样激活显存峰值可达数十 GB，触发 OOM 或被迫降 batch…</td></tr><tr><td>一句话机制</td><td>把 latent 按空间切块，逐块过 VAE 解码器并在通道维拼接，块间用重叠 halo 消除边界伪影；解码与 DiT…</td></tr><tr><td>代价与失效</td><td>halo 重叠与融合引入额外计算与边界伪影风险，tile 尺寸需按模型调参；分块解码 kernel 形状小、launch 频繁，GPU 利…</td></tr><tr><td>后继</td><td>DiT NVFP4 混合精度</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-vae-tiled-decode · 共 8 个片段</p>\n";break;}}})();
